//! Duration parser compatible with the human friendly duration syntax
//! (e.g. `10s`, `1h 30m`, `1.5s`).

use std::fmt;
use std::time::Duration;

#[derive(Debug, Clone, PartialEq)]
pub enum DurationError {
    InvalidCharacter(usize),
    NumberExpected(usize),
    UnknownUnit { unit: String, value: u64 },
    NumberOverflow,
    Empty,
}

impl fmt::Display for DurationError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            DurationError::InvalidCharacter(off) => write!(f, "invalid character at {}", off),
            DurationError::NumberExpected(off) => write!(f, "expected number at {}", off),
            DurationError::UnknownUnit { unit, value } if unit.is_empty() => {
                write!(f, "time unit needed, for example {0}sec or {0}ms", value)
            }
            DurationError::UnknownUnit { unit, .. } => write!(
                f,
                "unknown time unit {:?}, supported units: ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)",
                unit
            ),
            DurationError::NumberOverflow => write!(
                f,
                "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)"
            ),
            DurationError::Empty => write!(f, "value was empty"),
        }
    }
}

impl std::error::Error for DurationError {}

#[derive(Clone, Copy)]
struct Frac {
    num: u64,
    den: u64,
}

struct Parser<'a> {
    src: &'a str,
    chars: Vec<(usize, char)>,
    pos: usize,
    secs: u64,
    nanos: u64,
}

fn unit_nanos(unit: &str) -> Option<u128> {
    let v: u128 = match unit {
        "nanos" | "nsec" | "ns" => 1,
        "usec" | "us" | "µs" => 1_000,
        "millis" | "msec" | "ms" => 1_000_000,
        "seconds" | "second" | "secs" | "sec" | "s" => 1_000_000_000,
        "minutes" | "minute" | "min" | "mins" | "m" => 60 * 1_000_000_000,
        "hours" | "hour" | "hr" | "hrs" | "h" => 3600 * 1_000_000_000,
        "days" | "day" | "d" => 86400 * 1_000_000_000,
        "weeks" | "week" | "w" => 7 * 86400 * 1_000_000_000,
        "months" | "month" | "M" => 2_630_016 * 1_000_000_000,
        "years" | "year" | "y" => 31_557_600 * 1_000_000_000,
        _ => return None,
    };
    Some(v)
}

fn is_unit_char(c: char) -> bool {
    c.is_ascii_alphabetic() || c == 'µ'
}

impl<'a> Parser<'a> {
    fn off(&self) -> usize {
        if self.pos < self.chars.len() {
            self.chars[self.pos].0
        } else {
            self.src.len()
        }
    }
    fn next(&mut self) -> Option<char> {
        if self.pos < self.chars.len() {
            let c = self.chars[self.pos].1;
            self.pos += 1;
            Some(c)
        } else {
            None
        }
    }
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).map(|x| x.1)
    }

    fn parse_first_char(&mut self) -> Result<Option<u64>, DurationError> {
        let off = self.off();
        while let Some(c) = self.next() {
            match c {
                '0'..='9' => return Ok(Some(c as u64 - '0' as u64)),
                c if c.is_whitespace() => continue,
                _ => return Err(DurationError::NumberExpected(off)),
            }
        }
        Ok(None)
    }

    fn add_unit(&mut self, n: u64, frac: Option<Frac>, start: usize, end: usize) -> Result<(), DurationError> {
        let unit = &self.src[start..end];
        let un = match unit_nanos(unit) {
            Some(u) => u,
            None => {
                return Err(DurationError::UnknownUnit { unit: unit.to_string(), value: n });
            }
        };
        let mut total: u128 = (n as u128).checked_mul(un).ok_or(DurationError::NumberOverflow)?;
        if let Some(fr) = frac {
            let x = (fr.num as u128) * un;
            if x % (fr.den as u128) != 0 {
                return Err(DurationError::NumberOverflow);
            }
            total += x / (fr.den as u128);
        }
        let add_secs = total / 1_000_000_000;
        let add_nanos = (total % 1_000_000_000) as u64;
        if add_secs > u64::MAX as u128 {
            return Err(DurationError::NumberOverflow);
        }
        let mut secs = self.secs.checked_add(add_secs as u64).ok_or(DurationError::NumberOverflow)?;
        let mut nanos = self.nanos + add_nanos;
        if nanos >= 1_000_000_000 {
            secs = secs.checked_add(nanos / 1_000_000_000).ok_or(DurationError::NumberOverflow)?;
            nanos %= 1_000_000_000;
        }
        self.secs = secs;
        self.nanos = nanos;
        Ok(())
    }

    fn parse(mut self) -> Result<Duration, DurationError> {
        let mut n = self.parse_first_char()?.ok_or(DurationError::Empty)?;
        loop {
            // number part
            let mut frac: Option<Frac> = None;
            let mut off = self.off();
            let mut unit_start: Option<usize> = None;
            while let Some(c) = self.next() {
                match c {
                    '0'..='9' => {
                        let d = c as u64 - '0' as u64;
                        if let Some(fr) = frac.as_mut() {
                            fr.num = fr.num.checked_mul(10).and_then(|x| x.checked_add(d)).ok_or(DurationError::NumberOverflow)?;
                            fr.den = fr.den.checked_mul(10).ok_or(DurationError::NumberOverflow)?;
                        } else {
                            n = n.checked_mul(10).and_then(|x| x.checked_add(d)).ok_or(DurationError::NumberOverflow)?;
                        }
                    }
                    '.' if frac.is_none() => {
                        // must be followed by a digit (whitespace allowed)
                        let dot_off = off;
                        let mut p = self.pos;
                        let mut ok = false;
                        while p < self.chars.len() {
                            let cc = self.chars[p].1;
                            if cc.is_ascii_digit() {
                                ok = true;
                                break;
                            } else if cc.is_whitespace() {
                                p += 1;
                                continue;
                            } else {
                                break;
                            }
                        }
                        if !ok {
                            return Err(DurationError::InvalidCharacter(dot_off));
                        }
                        frac = Some(Frac { num: 0, den: 1 });
                    }
                    c if c.is_whitespace() => {}
                    c if is_unit_char(c) => {
                        unit_start = Some(off);
                        break;
                    }
                    _ => return Err(DurationError::InvalidCharacter(off)),
                }
                off = self.off();
            }
            let start = unit_start.unwrap_or(off);
            // unit part
            let mut off = self.off();
            let mut next_number: Option<u64> = None;
            if unit_start.is_some() {
                while let Some(c) = self.next() {
                    match c {
                        '0'..='9' => {
                            next_number = Some(c as u64 - '0' as u64);
                            break;
                        }
                        c if c.is_whitespace() => break,
                        c if is_unit_char(c) => {}
                        _ => return Err(DurationError::InvalidCharacter(off)),
                    }
                    off = self.off();
                }
            }
            let end = off;
            self.add_unit(n, frac, start, end)?;
            if let Some(nn) = next_number {
                n = nn;
                continue;
            }
            n = match self.parse_first_char()? {
                Some(n) => n,
                None => return Ok(Duration::new(self.secs, self.nanos as u32)),
            };
        }
    }
}

pub fn parse_duration(s: &str) -> Result<Duration, DurationError> {
    let p = Parser {
        src: s,
        chars: s.char_indices().collect(),
        pos: 0,
        secs: 0,
        nanos: 0,
    };
    let _ = p.peek();
    p.parse()
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn basic() {
        assert_eq!(parse_duration("10s").unwrap(), Duration::from_secs(10));
        assert_eq!(parse_duration("1.5s").unwrap(), Duration::from_millis(1500));
        assert_eq!(parse_duration("1s 500ms").unwrap(), Duration::from_millis(1500));
        assert_eq!(parse_duration("1s500ms").unwrap(), Duration::from_millis(1500));
        assert_eq!(parse_duration("1 2s").unwrap(), Duration::from_secs(12));
        assert_eq!(parse_duration("10").unwrap_err().to_string(), "time unit needed, for example 10sec or 10ms");
        assert_eq!(parse_duration("abc").unwrap_err().to_string(), "expected number at 0");
        assert_eq!(parse_duration("1s-").unwrap_err().to_string(), "invalid character at 2");
        assert_eq!(parse_duration("1.s").unwrap_err().to_string(), "invalid character at 1");
        assert_eq!(parse_duration("1.5.5s").unwrap_err().to_string(), "invalid character at 3");
        assert_eq!(parse_duration("1s,2s").unwrap_err().to_string(), "invalid character at 2");
        assert_eq!(parse_duration("").unwrap_err().to_string(), "value was empty");
        assert_eq!(parse_duration("1s 2").unwrap_err().to_string(), "time unit needed, for example 2sec or 2ms");
        assert!(parse_duration("1. 5ms").is_ok());
        assert!(parse_duration("0.5ns").is_err());
        assert!(parse_duration("0.001us").is_ok());
        assert!(parse_duration("1.10000000000s").is_ok());
        assert!(parse_duration("1.000000000000000000000000s").is_err());
    }
}
