//! Minimal DNS resolver: /etc/hosts + UDP queries to the nameservers in /etc/resolv.conf.

use std::io;
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr, SocketAddr, UdpSocket};
use std::time::Duration;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Strategy {
    Ipv4ThenIpv6,
    Ipv4Only,
    Ipv6Only,
}

pub fn strip_brackets(host: &str) -> &str {
    if host.starts_with('[') && host.ends_with(']') && host.len() >= 2 {
        &host[1..host.len() - 1]
    } else {
        host
    }
}

fn read_hosts(name: &str) -> (Vec<Ipv4Addr>, Vec<Ipv6Addr>) {
    let mut v4 = Vec::new();
    let mut v6 = Vec::new();
    if let Ok(s) = std::fs::read_to_string("/etc/hosts") {
        for line in s.lines() {
            let line = match line.find('#') {
                Some(i) => &line[..i],
                None => line,
            };
            let mut it = line.split_whitespace();
            let addr = match it.next() {
                Some(a) => a,
                None => continue,
            };
            let ip: IpAddr = match addr.parse() {
                Ok(ip) => ip,
                Err(_) => continue,
            };
            if it.any(|h| h.eq_ignore_ascii_case(name)) {
                match ip {
                    IpAddr::V4(a) => {
                        if !v4.contains(&a) {
                            v4.push(a)
                        }
                    }
                    IpAddr::V6(a) => {
                        if !v6.contains(&a) {
                            v6.push(a)
                        }
                    }
                }
            }
        }
    }
    (v4, v6)
}

fn nameservers() -> Vec<IpAddr> {
    let mut out = Vec::new();
    if let Ok(s) = std::fs::read_to_string("/etc/resolv.conf") {
        for line in s.lines() {
            let line = line.trim();
            if let Some(rest) = line.strip_prefix("nameserver") {
                if let Ok(ip) = rest.trim().parse::<IpAddr>() {
                    out.push(ip);
                }
            }
        }
    }
    if out.is_empty() {
        out.push(IpAddr::V4(Ipv4Addr::new(127, 0, 0, 1)));
    }
    out
}

fn encode_query(id: u16, name: &str, qtype: u16) -> Vec<u8> {
    let mut q = Vec::new();
    q.extend_from_slice(&id.to_be_bytes());
    q.extend_from_slice(&[0x01, 0x00]); // recursion desired
    q.extend_from_slice(&[0, 1, 0, 0, 0, 0, 0, 0]);
    for label in name.trim_end_matches('.').split('.') {
        let l = label.as_bytes();
        q.push(l.len().min(63) as u8);
        q.extend_from_slice(&l[..l.len().min(63)]);
    }
    q.push(0);
    q.extend_from_slice(&qtype.to_be_bytes());
    q.extend_from_slice(&[0, 1]);
    q
}

fn skip_name(buf: &[u8], mut pos: usize) -> Option<usize> {
    loop {
        let l = *buf.get(pos)? as usize;
        if l == 0 {
            return Some(pos + 1);
        }
        if l & 0xc0 == 0xc0 {
            return Some(pos + 2);
        }
        pos += 1 + l;
    }
}

fn parse_answer(buf: &[u8], qtype: u16) -> Option<(u8, Vec<IpAddr>)> {
    if buf.len() < 12 {
        return None;
    }
    let rcode = buf[3] & 0x0f;
    let qd = u16::from_be_bytes([buf[4], buf[5]]) as usize;
    let an = u16::from_be_bytes([buf[6], buf[7]]) as usize;
    let mut pos = 12;
    for _ in 0..qd {
        pos = skip_name(buf, pos)? + 4;
    }
    let mut out = Vec::new();
    for _ in 0..an {
        pos = skip_name(buf, pos)?;
        if pos + 10 > buf.len() {
            break;
        }
        let t = u16::from_be_bytes([buf[pos], buf[pos + 1]]);
        let rdlen = u16::from_be_bytes([buf[pos + 8], buf[pos + 9]]) as usize;
        pos += 10;
        if pos + rdlen > buf.len() {
            break;
        }
        if t == qtype {
            if t == 1 && rdlen == 4 {
                out.push(IpAddr::V4(Ipv4Addr::new(buf[pos], buf[pos + 1], buf[pos + 2], buf[pos + 3])));
            } else if t == 28 && rdlen == 16 {
                let mut a = [0u8; 16];
                a.copy_from_slice(&buf[pos..pos + 16]);
                out.push(IpAddr::V6(Ipv6Addr::from(a)));
            }
        }
        pos += rdlen;
    }
    Some((rcode, out))
}

fn query(name: &str, qtype: u16) -> Result<Vec<IpAddr>, String> {
    let servers = nameservers();
    let mut last_err = String::new();
    let qname = if name.ends_with('.') { name.to_string() } else { format!("{}.", name) };
    for server in servers {
        let bind: SocketAddr = match server {
            IpAddr::V4(_) => "0.0.0.0:0".parse().unwrap(),
            IpAddr::V6(_) => "[::]:0".parse().unwrap(),
        };
        let sock = match UdpSocket::bind(bind) {
            Ok(s) => s,
            Err(e) => {
                last_err = format!("proto error: io error: {}", e);
                continue;
            }
        };
        let _ = sock.set_read_timeout(Some(Duration::from_secs(5)));
        let id: u16 = rand::random();
        let q = encode_query(id, name, qtype);
        if let Err(e) = sock.send_to(&q, SocketAddr::new(server, 53)) {
            last_err = format!("proto error: io error: {}", e);
            continue;
        }
        let mut buf = [0u8; 2048];
        match sock.recv_from(&mut buf) {
            Ok((n, _)) => {
                if let Some((rcode, ips)) = parse_answer(&buf[..n], qtype) {
                    if rcode == 0 || rcode == 3 {
                        if ips.is_empty() {
                            let t = if qtype == 1 { "A" } else { "AAAA" };
                            return Err(format!(
                                "no record found for Query {{ name: Name(\"{}\"), query_type: {}, query_class: IN }}",
                                qname, t
                            ));
                        }
                        return Ok(ips);
                    }
                }
                last_err = "proto error: io error: invalid response".to_string();
            }
            Err(e) => {
                if e.kind() == io::ErrorKind::WouldBlock || e.kind() == io::ErrorKind::TimedOut {
                    last_err = "request timed out".to_string();
                } else {
                    last_err = format!("proto error: io error: {}", e);
                }
            }
        }
    }
    Err(last_err)
}

/// Resolve a host name (without brackets) to a list of IP addresses.
pub fn resolve(host: &str, strategy: Strategy) -> Result<Vec<IpAddr>, String> {
    let host = strip_brackets(host);
    if let Ok(ip) = host.parse::<IpAddr>() {
        return Ok(vec![ip]);
    }
    let (v4, v6) = read_hosts(host);
    match strategy {
        Strategy::Ipv4Only => {
            if !v4.is_empty() {
                return Ok(v4.into_iter().map(IpAddr::V4).collect());
            }
            query(host, 1)
        }
        Strategy::Ipv6Only => {
            if !v6.is_empty() {
                return Ok(v6.into_iter().map(IpAddr::V6).collect());
            }
            query(host, 28)
        }
        Strategy::Ipv4ThenIpv6 => {
            if !v4.is_empty() {
                return Ok(v4.into_iter().map(IpAddr::V4).collect());
            }
            if !v6.is_empty() {
                return Ok(v6.into_iter().map(IpAddr::V6).collect());
            }
            match query(host, 1) {
                Ok(v) => Ok(v),
                Err(e) => match query(host, 28) {
                    Ok(v) => Ok(v),
                    Err(_) => Err(e),
                },
            }
        }
    }
}
