pub const SSL_ERROR_WANT_READ: c_int = 2;
pub const SSL_ERROR_WANT_WRITE: c_int = 3;
pub const SSL_ERROR_SYSCALL: c_int = 5;
pub const SSL_ERROR_ZERO_RETURN: c_int = 6;

pub struct TlsContext {
    ctx: *mut SSL_CTX,
    pub insecure: bool,
}

unsafe impl Send for TlsContext {}
unsafe impl Sync for TlsContext {}

impl Drop for TlsContext {
    fn drop(&mut self) {
        unsafe { SSL_CTX_free(self.ctx) }
    }
}

fn last_error_string() -> String {
    unsafe {
        let e = ERR_get_error();
        if e == 0 {
            return "unknown TLS error".to_string();
        }
        let mut buf = [0 as c_char; 256];
        ERR_error_string_n(e, buf.as_mut_ptr(), buf.len());
        ERR_clear_error();
        CStr::from_ptr(buf.as_ptr()).to_string_lossy().into_owned()
    }
}

impl TlsContext {
    pub fn new(
        insecure: bool,
        cacert: Option<&str>,
        cert: Option<&str>,
        key: Option<&str>,
        alpn: &[&[u8]],
    ) -> Result<Arc<TlsContext>, String> {
        unsafe {
            let ctx = SSL_CTX_new(TLS_client_method());
            if ctx.is_null() {
                return Err(last_error_string());
            }
            let c = TlsContext { ctx, insecure };
            SSL_CTX_ctrl(
                ctx,
                SSL_CTRL_MODE,
                SSL_MODE_ENABLE_PARTIAL_WRITE | SSL_MODE_ACCEPT_MOVING_WRITE_BUFFER,
                std::ptr::null_mut(),
            );
            if insecure {
                SSL_CTX_set_verify(ctx, SSL_VERIFY_NONE, std::ptr::null());
            } else {
                SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER, std::ptr::null());
            }
            SSL_CTX_set_default_verify_paths(ctx);
            if let Some(ca) = cacert {
                let p = CString::new(ca).unwrap();
                if SSL_CTX_load_verify_locations(ctx, p.as_ptr(), std::ptr::null()) != 1 {
                    ERR_clear_error();
                }
            }
            if let (Some(cert), Some(key)) = (cert, key) {
                let cp = CString::new(cert).unwrap();
                let kp = CString::new(key).unwrap();
                if SSL_CTX_use_certificate_chain_file(ctx, cp.as_ptr()) != 1 {
                    return Err(last_error_string());
                }
                if SSL_CTX_use_PrivateKey_file(ctx, kp.as_ptr(), SSL_FILETYPE_PEM) != 1 {
                    return Err(last_error_string());
                }
            }
            if !alpn.is_empty() {
                let mut wire = Vec::new();
                for p in alpn {
                    wire.push(p.len() as u8);
                    wire.extend_from_slice(p);
                }
                SSL_CTX_set_alpn_protos(ctx, wire.as_ptr(), wire.len() as c_uint);
            }
            Ok(Arc::new(c))
        }
    }
}

pub struct TlsSession {
    ssl: *mut SSL,
    _ctx: Arc<TlsContext>,
}

unsafe impl Send for TlsSession {}

impl Drop for TlsSession {
    fn drop(&mut self) {
        unsafe {
            SSL_shutdown(self.ssl);
            SSL_free(self.ssl);
        }
    }
}

pub enum IoStatus {
    Done(usize),
    WantRead,
    WantWrite,
    Eof,
    Error(String),
}

impl TlsSession {
    pub fn new(ctx: Arc<TlsContext>, fd: RawFd, server_name: &str) -> Result<TlsSession, String> {
        unsafe {
            let ssl = SSL_new(ctx.ctx);
            if ssl.is_null() {
                return Err(last_error_string());
            }
            SSL_set_fd(ssl, fd);
            let is_ip = server_name.parse::<std::net::IpAddr>().is_ok();
            let name = CString::new(server_name).unwrap_or_default();
            if !is_ip {
                SSL_ctrl(ssl, SSL_CTRL_SET_TLSEXT_HOSTNAME, 0, name.as_ptr() as *mut c_void);
            }
            if !ctx.insecure {
                SSL_set1_host(ssl, name.as_ptr());
            }
            Ok(TlsSession { ssl, _ctx: ctx })
        }
    }

    fn status(&self, ret: c_int) -> IoStatus {
        unsafe {
            let e = SSL_get_error(self.ssl, ret);
            match e {
                SSL_ERROR_WANT_READ => IoStatus::WantRead,
                SSL_ERROR_WANT_WRITE => IoStatus::WantWrite,
                SSL_ERROR_ZERO_RETURN => IoStatus::Eof,
                SSL_ERROR_SYSCALL => {
                    let errno = std::io::Error::last_os_error();
                    ERR_clear_error();
                    if ret == 0 || errno.raw_os_error() == Some(0) {
                        IoStatus::Eof
                    } else {
                        IoStatus::Error(errno.to_string())
                    }
                }
                _ => IoStatus::Error(last_error_string()),
            }
        }
    }

    pub fn handshake(&mut self) -> IoStatus {
        unsafe {
            let r = SSL_connect(self.ssl);
            if r == 1 {
                IoStatus::Done(0)
            } else {
                self.status(r)
            }
        }
    }

    /// Describe a handshake failure similar to rustls error messages.
    pub fn verify_error(&self) -> Option<String> {
        unsafe {
            let v = SSL_get_verify_result(self.ssl);
            if v == 0 {
                return None;
            }
            let cert = SSL_get1_peer_certificate(self.ssl);
            let mut is_ca = false;
            if !cert.is_null() {
                is_ca = X509_check_ca(cert) != 0;
                X509_free(cert);
            }
            let msg = match v {
                62 => "invalid peer certificate: NotValidForName".to_string(),
                10 => "invalid peer certificate: Expired".to_string(),
                9 => "invalid peer certificate: NotValidYet".to_string(),
                _ => {
                    if is_ca {
                        "invalid peer certificate: Other(OtherError(CaUsedAsEndEntity))".to_string()
                    } else {
                        "invalid peer certificate: UnknownIssuer".to_string()
                    }
                }
            };
            Some(msg)
        }
    }

    pub fn peer_is_ca(&self) -> bool {
        unsafe {
            let cert = SSL_get1_peer_certificate(self.ssl);
            if cert.is_null() {
                return false;
            }
            let r = X509_check_ca(cert) != 0;
            X509_free(cert);
            r
        }
    }

    pub fn alpn(&self) -> Option<Vec<u8>> {
        unsafe {
            let mut p: *const u8 = std::ptr::null();
            let mut l: c_uint = 0;
            SSL_get0_alpn_selected(self.ssl, &mut p, &mut l);
            if p.is_null() || l == 0 {
                None
            } else {
                Some(std::slice::from_raw_parts(p, l as usize).to_vec())
            }
        }
    }

    pub fn pending(&self) -> usize {
        unsafe { SSL_pending(self.ssl) as usize }
    }

    pub fn read(&mut self, buf: &mut [u8]) -> IoStatus {
        unsafe {
            let n = buf.len().min(i32::MAX as usize) as c_int;
            let r = SSL_read(self.ssl, buf.as_mut_ptr() as *mut c_void, n);
            if r > 0 {
                IoStatus::Done(r as usize)
            } else {
                self.status(r)
            }
        }
    }

    pub fn write(&mut self, buf: &[u8]) -> IoStatus {
        unsafe {
            let n = buf.len().min(i32::MAX as usize) as c_int;
            let r = SSL_write(self.ssl, buf.as_ptr() as *const c_void, n);
            if r > 0 {
                IoStatus::Done(r as usize)
            } else {
                self.status(r)
            }
        }
    }
}
