//! Low level networking: non-blocking sockets with deadline aware I/O.

use crate::tls::{IoStatus, TlsContext, TlsSession};
use std::io;
use std::net::{IpAddr, SocketAddr, TcpStream};
use std::os::unix::io::{AsRawFd, FromRawFd, RawFd};
use std::os::unix::net::UnixStream;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

/// Set when the whole benchmark must stop immediately (Ctrl-C, `q`, deadline).
pub static ABORT: AtomicBool = AtomicBool::new(false);

#[derive(Debug, Clone)]
pub enum NetError {
    /// per request timeout elapsed
    Timeout,
    /// benchmark deadline / abort
    Aborted,
    Eof,
    Io(String, io::ErrorKind),
    Tls(String),
}

#[derive(Clone, Copy, Default)]
pub struct Limits {
    pub timeout: Option<Instant>,
    pub deadline: Option<Instant>,
    /// whether the global ABORT flag aborts this I/O
    pub abortable: bool,
}

impl Limits {
    fn check(&self) -> Result<Option<Duration>, NetError> {
        let now = Instant::now();
        if self.abortable && ABORT.load(Ordering::Relaxed) {
            return Err(NetError::Aborted);
        }
        if let Some(d) = self.deadline {
            if now >= d {
                return Err(NetError::Aborted);
            }
        }
        if let Some(t) = self.timeout {
            if now >= t {
                return Err(NetError::Timeout);
            }
        }
        let mut wait = Duration::from_millis(50);
        for x in [self.deadline, self.timeout].into_iter().flatten() {
            let rem = x.saturating_duration_since(now);
            if rem < wait {
                wait = rem;
            }
        }
        Ok(Some(wait))
    }
}

/// Wait for the fd to become readable/writable honoring limits.
pub fn wait_fd(fd: RawFd, write: bool, limits: &Limits) -> Result<(), NetError> {
    loop {
        let wait = limits.check()?.unwrap_or(Duration::from_millis(50));
        let mut pfd = libc::pollfd {
            fd,
            events: if write { libc::POLLOUT } else { libc::POLLIN },
            revents: 0,
        };
        let ms = (wait.as_micros() as i64 + 999) / 1000;
        let r = unsafe { libc::poll(&mut pfd, 1, ms.max(0) as i32) };
        if r < 0 {
            let e = io::Error::last_os_error();
            if e.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(NetError::Io(e.to_string(), e.kind()));
        }
        if r > 0 {
            return Ok(());
        }
    }
}

fn set_nonblocking(fd: RawFd) {
    unsafe {
        let flags = libc::fcntl(fd, libc::F_GETFL);
        libc::fcntl(fd, libc::F_SETFL, flags | libc::O_NONBLOCK);
    }
}

fn sockaddr(addr: &SocketAddr) -> (libc::sockaddr_storage, libc::socklen_t) {
    unsafe {
        let mut storage: libc::sockaddr_storage = std::mem::zeroed();
        match addr {
            SocketAddr::V4(a) => {
                let sin = &mut *(&mut storage as *mut _ as *mut libc::sockaddr_in);
                sin.sin_family = libc::AF_INET as libc::sa_family_t;
                sin.sin_port = a.port().to_be();
                sin.sin_addr.s_addr = u32::from_ne_bytes(a.ip().octets());
                (storage, std::mem::size_of::<libc::sockaddr_in>() as libc::socklen_t)
            }
            SocketAddr::V6(a) => {
                let sin6 = &mut *(&mut storage as *mut _ as *mut libc::sockaddr_in6);
                sin6.sin6_family = libc::AF_INET6 as libc::sa_family_t;
                sin6.sin6_port = a.port().to_be();
                sin6.sin6_addr.s6_addr = a.ip().octets();
                sin6.sin6_scope_id = a.scope_id();
                (storage, std::mem::size_of::<libc::sockaddr_in6>() as libc::socklen_t)
            }
        }
    }
}

fn io_err(e: io::Error) -> NetError {
    NetError::Io(e.to_string(), e.kind())
}

pub fn tcp_connect(ip: IpAddr, port: u16, connect_timeout: Duration, limits: &Limits) -> Result<TcpStream, NetError> {
    let addr = SocketAddr::new(ip, port);
    let domain = match addr {
        SocketAddr::V4(_) => libc::AF_INET,
        SocketAddr::V6(_) => libc::AF_INET6,
    };
    let fd = unsafe { libc::socket(domain, libc::SOCK_STREAM | libc::SOCK_CLOEXEC, 0) };
    if fd < 0 {
        return Err(io_err(io::Error::last_os_error()));
    }
    let stream = unsafe { TcpStream::from_raw_fd(fd) };
    set_nonblocking(fd);
    let (sa, len) = sockaddr(&addr);
    let r = unsafe { libc::connect(fd, &sa as *const _ as *const libc::sockaddr, len) };
    if r != 0 {
        let e = io::Error::last_os_error();
        if e.raw_os_error() != Some(libc::EINPROGRESS) {
            return Err(io_err(e));
        }
        let mut l = *limits;
        let ct = Instant::now() + connect_timeout;
        l.timeout = Some(match l.timeout {
            Some(t) if t < ct => t,
            _ => ct,
        });
        wait_fd(fd, true, &l)?;
        let mut err: libc::c_int = 0;
        let mut elen = std::mem::size_of::<libc::c_int>() as libc::socklen_t;
        unsafe {
            libc::getsockopt(fd, libc::SOL_SOCKET, libc::SO_ERROR, &mut err as *mut _ as *mut libc::c_void, &mut elen);
        }
        if err != 0 {
            return Err(io_err(io::Error::from_raw_os_error(err)));
        }
    }
    let _ = stream.set_nodelay(true);
    Ok(stream)
}

pub fn unix_connect(path: &str) -> Result<UnixStream, NetError> {
    let s = UnixStream::connect(path).map_err(io_err)?;
    s.set_nonblocking(true).map_err(io_err)?;
    Ok(s)
}

pub enum Transport {
    Tcp(TcpStream),
    Unix(UnixStream),
}

impl Transport {
    pub fn fd(&self) -> RawFd {
        match self {
            Transport::Tcp(s) => s.as_raw_fd(),
            Transport::Unix(s) => s.as_raw_fd(),
        }
    }
}

pub struct Conn {
    pub transport: Transport,
    pub tls: Option<TlsSession>,
}

impl Conn {
    pub fn plain(t: Transport) -> Conn {
        Conn { transport: t, tls: None }
    }

    pub fn fd(&self) -> RawFd {
        self.transport.fd()
    }

    pub fn start_tls(&mut self, ctx: Arc<TlsContext>, server_name: &str, limits: &Limits) -> Result<(), NetError> {
        let fd = self.fd();
        let mut sess = TlsSession::new(ctx, fd, server_name).map_err(NetError::Tls)?;
        loop {
            match sess.handshake() {
                IoStatus::Done(_) => break,
                IoStatus::WantRead => wait_fd(fd, false, limits)?,
                IoStatus::WantWrite => wait_fd(fd, true, limits)?,
                IoStatus::Eof => {
                    if let Some(v) = sess.verify_error() {
                        return Err(NetError::Tls(v));
                    }
                    return Err(NetError::Tls("tls handshake eof".to_string()));
                }
                IoStatus::Error(e) => {
                    if let Some(v) = sess.verify_error() {
                        return Err(NetError::Tls(v));
                    }
                    if e.contains("wrong version number") || e.contains("packet length too long") || e.contains("record layer failure") {
                        return Err(NetError::Tls("received corrupt message of type InvalidContentType".to_string()));
                    }
                    return Err(NetError::Tls(e));
                }
            }
        }
        // rustls rejects CA certificates used as end entity even when trusted
        if !sess_insecure(&sess) && sess.peer_is_ca() {
            return Err(NetError::Tls("invalid peer certificate: Other(OtherError(CaUsedAsEndEntity))".to_string()));
        }
        self.tls = Some(sess);
        Ok(())
    }

    pub fn alpn(&self) -> Option<Vec<u8>> {
        self.tls.as_ref().and_then(|t| t.alpn())
    }

    /// Read some bytes. Returns Ok(0) on EOF.
    pub fn read(&mut self, buf: &mut [u8], limits: &Limits) -> Result<usize, NetError> {
        let fd = self.fd();
        loop {
            if let Some(tls) = self.tls.as_mut() {
                match tls.read(buf) {
                    IoStatus::Done(n) => return Ok(n),
                    IoStatus::Eof => return Ok(0),
                    IoStatus::WantRead => {
                        limits.check()?;
                        wait_fd(fd, false, limits)?
                    }
                    IoStatus::WantWrite => wait_fd(fd, true, limits)?,
                    IoStatus::Error(e) => return Err(NetError::Io(e, io::ErrorKind::Other)),
                }
            } else {
                let r = unsafe { libc::read(fd, buf.as_mut_ptr() as *mut libc::c_void, buf.len()) };
                if r >= 0 {
                    return Ok(r as usize);
                }
                let e = io::Error::last_os_error();
                match e.kind() {
                    io::ErrorKind::WouldBlock => {
                        limits.check()?;
                        wait_fd(fd, false, limits)?
                    }
                    io::ErrorKind::Interrupted => {}
                    _ => return Err(io_err(e)),
                }
            }
        }
    }

    pub fn write_all(&mut self, mut data: &[u8], limits: &Limits) -> Result<(), NetError> {
        let fd = self.fd();
        while !data.is_empty() {
            if let Some(tls) = self.tls.as_mut() {
                match tls.write(data) {
                    IoStatus::Done(n) => data = &data[n..],
                    IoStatus::WantRead => wait_fd(fd, false, limits)?,
                    IoStatus::WantWrite => wait_fd(fd, true, limits)?,
                    IoStatus::Eof => return Err(NetError::Eof),
                    IoStatus::Error(e) => return Err(NetError::Io(e, io::ErrorKind::Other)),
                }
            } else {
                let r = unsafe {
                    libc::send(fd, data.as_ptr() as *const libc::c_void, data.len(), libc::MSG_NOSIGNAL)
                };
                if r >= 0 {
                    data = &data[r as usize..];
                    continue;
                }
                let e = io::Error::last_os_error();
                match e.kind() {
                    io::ErrorKind::WouldBlock => wait_fd(fd, true, limits)?,
                    io::ErrorKind::Interrupted => {}
                    _ => return Err(io_err(e)),
                }
            }
        }
        Ok(())
    }

    /// Returns true if the peer has closed or sent unexpected data (connection unusable).
    pub fn is_stale(&mut self) -> bool {
        if let Some(tls) = self.tls.as_ref() {
            if tls.pending() > 0 {
                return true;
            }
        }
        let fd = self.fd();
        let mut pfd = libc::pollfd { fd, events: libc::POLLIN, revents: 0 };
        let r = unsafe { libc::poll(&mut pfd, 1, 0) };
        r > 0
    }
}

fn sess_insecure(s: &TlsSession) -> bool {
    let _ = s;
    crate::tls_insecure()
}
