pub fn unix_connect(path: &str) -> Result<UnixStream, NetError> {
    let s = UnixStream::connect(path).map_err(io_err)?;
    s.set_nonblocking(true).map_err(io_err)?;
    Ok(s)
}

pub enum Transport {
    Tcp(TcpStream),
    Unix(UnixStream),
}

impl Transport {
    pub fn fd(&self) -> RawFd {
        match self {
            Transport::Tcp(s) => s.as_raw_fd(),
            Transport::Unix(s) => s.as_raw_fd(),
        }
    }
}

pub struct Conn {
    pub transport: Transport,
    pub tls: Option<TlsSession>,
}

impl Conn {
    pub fn plain(t: Transport) -> Conn {
        Conn { transport: t, tls: None }
    }

    pub fn fd(&self) -> RawFd {
        self.transport.fd()
    }

    pub fn start_tls(&mut self, ctx: Arc<TlsContext>, server_name: &str, limits: &Limits) -> Result<(), NetError> {
        let fd = self.fd();
        let mut sess = TlsSession::new(ctx, fd, server_name).map_err(NetError::Tls)?;
        loop {
            match sess.handshake() {
                IoStatus::Done(_) => break,
                IoStatus::WantRead => wait_fd(fd, false, limits)?,
                IoStatus::WantWrite => wait_fd(fd, true, limits)?,
                IoStatus::Eof => {
                    if let Some(v) = sess.verify_error() {
                        return Err(NetError::Tls(v));
                    }
                    return Err(NetError::Tls("tls handshake eof".to_string()));
                }
                IoStatus::Error(e) => {
                    if let Some(v) = sess.verify_error() {
                        return Err(NetError::Tls(v));
                    }
                    if e.contains("wrong version number") || e.contains("packet length too long") || e.contains("record layer failure") {
                        return Err(NetError::Tls("received corrupt message of type InvalidContentType".to_string()));
                    }
                    return Err(NetError::Tls(e));
                }
            }
        }
        // rustls rejects CA certificates used as end entity even when trusted
        if !sess_insecure(&sess) && sess.peer_is_ca() {
            return Err(NetError::Tls("invalid peer certificate: Other(OtherError(CaUsedAsEndEntity))".to_string()));
        }
        self.tls = Some(sess);
        Ok(())
    }

    pub fn alpn(&self) -> Option<Vec<u8>> {
        self.tls.as_ref().and_then(|t| t.alpn())
    }

    /// Read some bytes. Returns Ok(0) on EOF.
    pub fn read(&mut self, buf: &mut [u8], limits: &Limits) -> Result<usize, NetError> {
        let fd = self.fd();
        loop {
            if let Some(tls) = self.tls.as_mut() {
                match tls.read(buf) {
                    IoStatus::Done(n) => return Ok(n),
                    IoStatus::Eof => return Ok(0),
                    IoStatus::WantRead => {
                        limits.check()?;
                        wait_fd(fd, false, limits)?
                    }
                    IoStatus::WantWrite => wait_fd(fd, true, limits)?,
                    IoStatus::Error(e) => return Err(NetError::Io(e, io::ErrorKind::Other)),
                }
            } else {
                let r = unsafe { libc::read(fd, buf.as_mut_ptr() as *mut libc::c_void, buf.len()) };
                if r >= 0 {
                    return Ok(r as usize);
                }
                let e = io::Error::last_os_error();
                match e.kind() {
                    io::ErrorKind::WouldBlock => {
                        limits.check()?;
                        wait_fd(fd, false, limits)?
                    }
                    io::ErrorKind::Interrupted => {}
                    _ => return Err(io_err(e)),
                }
            }
        }
    }

    pub fn write_all(&mut self, mut data: &[u8], limits: &Limits) -> Result<(), NetError> {
        let fd = self.fd();
        while !data.is_empty() {
            if let Some(tls) = self.tls.as_mut() {
                match tls.write(data) {
                    IoStatus::Done(n) => data = &data[n..],
                    IoStatus::WantRead => wait_fd(fd, false, limits)?,
                    IoStatus::WantWrite => wait_fd(fd, true, limits)?,
                    IoStatus::Eof => return Err(NetError::Eof),
                    IoStatus::Error(e) => return Err(NetError::Io(e, io::ErrorKind::Other)),
                }
            } else {
                let r = unsafe {
                    libc::send(fd, data.as_ptr() as *const libc::c_void, data.len(), libc::MSG_NOSIGNAL)
                };
                if r >= 0 {
                    data = &data[r as usize..];
                    continue;
                }
                let e = io::Error::last_os_error();
                match e.kind() {
                    io::ErrorKind::WouldBlock => wait_fd(fd, true, limits)?,
                    io::ErrorKind::Interrupted => {}
                    _ => return Err(io_err(e)),
                }
            }
        }
        Ok(())
    }

    /// Returns true if the peer has closed or sent unexpected data (connection unusable).
    pub fn is_stale(&mut self) -> bool {
        if let Some(tls) = self.tls.as_ref() {
            if tls.pending() > 0 {
                return true;
            }
        }
        let fd = self.fd();
        let mut pfd = libc::pollfd { fd, events: libc::POLLIN, revents: 0 };
        let r = unsafe { libc::poll(&mut pfd, 1, 0) };
        r > 0
    }
}

fn sess_insecure(s: &TlsSession) -> bool {
    let _ = s;
    crate::tls_insecure()
}
