        let colon = match l.iter().position(|&b| b == b':') {
            Some(c) => c,
            None => return Err(H1Error::Header),
        };
        let name = &l[..colon];
        if name.is_empty() || !name.iter().all(|&b| is_token(b)) {
            return Err(H1Error::Header);
        }
        let mut v = &l[colon + 1..];
        while let Some((&f, r)) = v.split_first() {
            if f == b' ' || f == b'\t' {
                v = r;
            } else {
                break;
            }
        }
        while let Some((&f, r)) = v.split_last() {
            if f == b' ' || f == b'\t' {
                v = r;
            } else {
                break;
            }
        }
        if v.iter().any(|&b| b < 0x20 && b != b'\t' || b == 0x7f) {
            return Err(H1Error::Header);
        }
        headers.push((String::from_utf8_lossy(name).to_ascii_lowercase(), v.to_vec()));
        if headers.len() > MAX_HEADERS {
            return Err(H1Error::TooLarge);
        }
