}

impl H1Conn {
    pub fn new(conn: Conn) -> H1Conn {
        H1Conn { conn, buf: vec![0u8; 16384], pos: 0, end: 0 }
    }

    fn fill(&mut self, limits: &Limits) -> Result<usize, NetError> {
        if self.pos > 0 && self.pos == self.end {
            self.pos = 0;
            self.end = 0;
        }
        if self.end == self.buf.len() {
            if self.pos > 0 {
                self.buf.copy_within(self.pos..self.end, 0);
                self.end -= self.pos;
                self.pos = 0;
            } else {
                let n = self.buf.len();
                self.buf.resize(n * 2, 0);
            }
        }
        let end = self.end;
        let n = self.conn.read(&mut self.buf[end..], limits)?;
        self.end += n;
        Ok(n)
    }

    pub fn has_buffered(&self) -> bool {
        self.pos < self.end
    }

    pub fn is_stale(&mut self) -> bool {
        self.has_buffered() || self.conn.is_stale()
    }

    fn read_head(&mut self, limits: &Limits) -> Result<ResponseHead, H1Error> {
        loop {
            if let Some(e) = find_head_end(&self.buf[self.pos..self.end]) {
                let raw = self.buf[self.pos..self.pos + e].to_vec();
                self.pos += e;
