                                return Err(H1Error::Version);
                            }
                        }
                    }
                    return Err(H1Error::Incomplete);
                }
                Ok(_) => {}
                Err(e @ NetError::Timeout) | Err(e @ NetError::Aborted) => return Err(H1Error::Net(e)),
                Err(e @ NetError::Tls(_)) => return Err(H1Error::Net(e)),
                Err(_) => return Err(H1Error::Conn),
            }
        }
    }

    fn body_err(e: NetError) -> H1Error {
        match e {
            NetError::Timeout | NetError::Aborted => H1Error::Net(e),
            _ => H1Error::Body,
        }
    }

    fn read_exact_body(&mut self, mut n: usize, keep: bool, out: &mut Vec<u8>, limits: &Limits) -> Result<usize, H1Error> {
        let mut total = 0;
        while n > 0 {
            if self.pos == self.end {
                match self.fill(limits) {
                    Ok(0) => return Err(H1Error::Body),
                    Ok(_) => {}
                    Err(e) => return Err(Self::body_err(e)),
                }
            }
            let avail = (self.end - self.pos).min(n);
            if keep {
                out.extend_from_slice(&self.buf[self.pos..self.pos + avail]);
            }
            self.pos += avail;
            n -= avail;
            total += avail;
        }
        Ok(total)
    }

    fn read_line(&mut self, limits: &Limits) -> Result<Vec<u8>, H1Error> {
        loop {
            if let Some(i) = self.buf[self.pos..self.end].iter().position(|&b| b == b'\n') {
