            if f == b' ' || f == b'\t' {
                v = r;
            } else {
                break;
            }
        }
        if v.iter().any(|&b| b < 0x20 && b != b'\t' || b == 0x7f) {
            return Err(H1Error::Header);
        }
        headers.push((String::from_utf8_lossy(name).to_ascii_lowercase(), v.to_vec()));
        if headers.len() > MAX_HEADERS {
            return Err(H1Error::TooLarge);
        }
    }
    Ok(ResponseHead { version, status, headers })
}

impl H1Conn {
    pub fn new(conn: Conn) -> H1Conn {
        H1Conn { conn, buf: vec![0u8; 16384], pos: 0, end: 0 }
    }

    fn fill(&mut self, limits: &Limits) -> Result<usize, NetError> {
        if self.pos > 0 && self.pos == self.end {
            self.pos = 0;
            self.end = 0;
        }
        if self.end == self.buf.len() {
            if self.pos > 0 {
                self.buf.copy_within(self.pos..self.end, 0);
                self.end -= self.pos;
                self.pos = 0;
            } else {
                let n = self.buf.len();
                self.buf.resize(n * 2, 0);
            }
        }
        let end = self.end;
        let n = self.conn.read(&mut self.buf[end..], limits)?;
        self.end += n;
        Ok(n)
    }

    pub fn has_buffered(&self) -> bool {
        self.pos < self.end
    }

    pub fn is_stale(&mut self) -> bool {
        self.has_buffered() || self.conn.is_stale()
    }

    fn read_head(&mut self, limits: &Limits) -> Result<ResponseHead, H1Error> {
        loop {
            if let Some(e) = find_head_end(&self.buf[self.pos..self.end]) {
                let raw = self.buf[self.pos..self.pos + e].to_vec();
                self.pos += e;
                if raw.len() > MAX_HEAD {
                    return Err(H1Error::TooLarge);
                }
                return parse_head(&raw);
            }
            if self.end - self.pos > MAX_HEAD {
                return Err(H1Error::TooLarge);
            }
            match self.fill(limits) {
                Ok(0) => {
                    // EOF: try to report parse errors on the partial data
                    if self.end > self.pos {
                        let partial = &self.buf[self.pos..self.end];
                        if partial.len() >= 5 && &partial[..5] != b"HTTP/" {
                            let trimmed: Vec<u8> = partial.iter().cloned().skip_while(|b| *b == b'\r' || *b == b'\n').collect();
                            if trimmed.len() >= 5 && &trimmed[..5] != b"HTTP/" {
                                return Err(H1Error::Version);
                            }
                        }
                    }
                    return Err(H1Error::Incomplete);
                }
                Ok(_) => {}
                Err(e @ NetError::Timeout) | Err(e @ NetError::Aborted) => return Err(H1Error::Net(e)),
                Err(e @ NetError::Tls(_)) => return Err(H1Error::Net(e)),
                Err(_) => return Err(H1Error::Conn),
            }
        }
    }

    fn body_err(e: NetError) -> H1Error {
        match e {
            NetError::Timeout | NetError::Aborted => H1Error::Net(e),
            _ => H1Error::Body,
        }
    }

    fn read_exact_body(&mut self, mut n: usize, keep: bool, out: &mut Vec<u8>, limits: &Limits) -> Result<usize, H1Error> {
        let mut total = 0;
        while n > 0 {
            if self.pos == self.end {
                match self.fill(limits) {
                    Ok(0) => return Err(H1Error::Body),
                    Ok(_) => {}
                    Err(e) => return Err(Self::body_err(e)),
                }
            }
            let avail = (self.end - self.pos).min(n);
            if keep {
                out.extend_from_slice(&self.buf[self.pos..self.pos + avail]);
            }
            self.pos += avail;
            n -= avail;
            total += avail;
        }
        Ok(total)
    }

    fn read_line(&mut self, limits: &Limits) -> Result<Vec<u8>, H1Error> {
        loop {
            if let Some(i) = self.buf[self.pos..self.end].iter().position(|&b| b == b'\n') {
                let mut l = self.buf[self.pos..self.pos + i].to_vec();
                self.pos += i + 1;
                if l.last() == Some(&b'\r') {
                    l.pop();
                }
                return Ok(l);
            }
            if self.end - self.pos > 4096 {
                return Err(H1Error::Body);
            }
            match self.fill(limits) {
                Ok(0) => return Err(H1Error::Body),
                Ok(_) => {}
                Err(e) => return Err(Self::body_err(e)),
            }
        }
    }

    fn read_chunked(&mut self, keep: bool, out: &mut Vec<u8>, limits: &Limits) -> Result<usize, H1Error> {
        let mut total = 0;
        loop {
            let line = self.read_line(limits)?;
            let s = String::from_utf8_lossy(&line);
            let size_str = s.split(';').next().unwrap_or("").trim();
            let size = usize::from_str_radix(size_str, 16).map_err(|_| H1Error::Body)?;
            if size == 0 {
                // trailers
                loop {
                    let l = self.read_line(limits)?;
                    if l.is_empty() {
                        break;
                    }
                }
                return Ok(total);
            }
            total += self.read_exact_body(size, keep, out, limits)?;
            let crlf = self.read_line(limits)?;
            if !crlf.is_empty() {
                return Err(H1Error::Body);
            }
        }
    }

    fn read_to_end(&mut self, keep: bool, out: &mut Vec<u8>, limits: &Limits) -> Result<usize, H1Error> {
        let mut total = 0;
        loop {
            if self.pos < self.end {
                let n = self.end - self.pos;
                if keep {
                    out.extend_from_slice(&self.buf[self.pos..self.end]);
                }
                total += n;
                self.pos = self.end;
            }
            match self.fill(limits) {
                Ok(0) => return Ok(total),
                Ok(_) => {}
                Err(e) => return Err(Self::body_err(e)),
            }
        }
    }

    /// Send a serialized request and read the response.
    pub fn round_trip(
        &mut self,
        request: &[u8],
        is_head: bool,
        request_close: bool,
        keep_body: bool,
        limits: &Limits,
    ) -> Result<Response, H1Error> {
        if let Err(e) = self.conn.write_all(request, limits) {
            return Err(match e {
                NetError::Timeout | NetError::Aborted | NetError::Tls(_) => H1Error::Net(e),
                _ => H1Error::Conn,
            });
        }
        let mut head;
        loop {
            head = self.read_head(limits)?;
            if head.status >= 100 && head.status < 200 && head.status != 101 {
                continue;
            }
            break;
        }
        let first_byte = Instant::now();
        let mut keep_alive = !request_close;
        let conn_hdr = head
            .header("connection")
            .map(|v| String::from_utf8_lossy(v).to_ascii_lowercase())
            .unwrap_or_default();
        if head.version == 10 {
            if !conn_hdr.split(',').any(|t| t.trim() == "keep-alive") {
                keep_alive = false;
            }
        } else if conn_hdr.split(',').any(|t| t.trim() == "close") {
            keep_alive = false;
        }
        let mut body = Vec::new();
        let body_len;
        let no_body = is_head || head.status == 204 || head.status == 304 || head.status == 101;
        if head.status == 101 {
            keep_alive = false;
        }
        if no_body {
            body_len = 0;
        } else {
            let te = head
                .headers
                .iter()
                .filter(|(k, _)| k == "transfer-encoding")
                .map(|(_, v)| String::from_utf8_lossy(v).to_ascii_lowercase())
                .collect::<Vec<_>>()
                .join(",");
            let chunked = !te.is_empty() && te.split(',').last().map(|t| t.trim() == "chunked").unwrap_or(false);
            if chunked {
                body_len = self.read_chunked(keep_body, &mut body, limits)?;
            } else if !te.is_empty() {
                body_len = self.read_to_end(keep_body, &mut body, limits)?;
                keep_alive = false;
            } else if let Some(cl) = head.header("content-length") {
                let s = String::from_utf8_lossy(cl);
                let n: usize = match s.trim().parse() {
                    Ok(n) => n,
                    Err(_) => return Err(H1Error::Header),
                };
                body_len = self.read_exact_body(n, keep_body, &mut body, limits)?;
            } else {
                body_len = self.read_to_end(keep_body, &mut body, limits)?;
                keep_alive = false;
            }
        }
        Ok(Response { head, body, body_len, first_byte, keep_alive })
    }
}
