//! Random string generation from a regular expression.

use rand::Rng;
use regex_syntax::hir::{Class, Hir, HirKind};
use std::fmt;

#[derive(Debug)]
pub enum RegexError {
    Syntax(Box<regex_syntax::Error>),
    Anchor,
    Unsatisfiable,
}

impl fmt::Display for RegexError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            RegexError::Syntax(e) => fmt::Display::fmt(e, f),
            RegexError::Anchor => f.write_str("anchor is not supported"),
            RegexError::Unsatisfiable => f.write_str("regex is unsatisfiable"),
        }
    }
}

enum Node {
    Literal(Vec<u8>),
    Unicode(Vec<(u32, u32)>, u64),
    Bytes(Vec<(u8, u8)>, u64),
    Repeat(Box<Node>, u32, u32),
    Concat(Vec<Node>),
    Alt(Vec<Node>),
}

pub struct RandRegex {
    root: Node,
}

fn compile(h: &Hir, max_repeat: u32) -> Result<Node, RegexError> {
    Ok(match h.kind() {
        HirKind::Empty => Node::Literal(Vec::new()),
        HirKind::Literal(l) => Node::Literal(l.0.to_vec()),
        HirKind::Class(Class::Unicode(c)) => {
            let ranges: Vec<(u32, u32)> = c.ranges().iter().map(|r| (r.start() as u32, r.end() as u32)).collect();
            let total: u64 = ranges.iter().map(|(a, b)| (*b - *a + 1) as u64).sum();
            if total == 0 {
                return Err(RegexError::Unsatisfiable);
            }
            Node::Unicode(ranges, total)
        }
        HirKind::Class(Class::Bytes(c)) => {
            let ranges: Vec<(u8, u8)> = c.ranges().iter().map(|r| (r.start(), r.end())).collect();
            let total: u64 = ranges.iter().map(|(a, b)| (*b as u64 - *a as u64 + 1)).sum();
            if total == 0 {
                return Err(RegexError::Unsatisfiable);
            }
            Node::Bytes(ranges, total)
        }
        HirKind::Look(_) => return Err(RegexError::Anchor),
        HirKind::Repetition(r) => {
            let min = r.min;
            let max = match r.max {
                Some(m) => m,
                None => min.saturating_add(max_repeat),
            };
            let sub = compile(&r.sub, max_repeat)?;
            Node::Repeat(Box::new(sub), min, max)
        }
        HirKind::Capture(c) => compile(&c.sub, max_repeat)?,
        HirKind::Concat(v) => Node::Concat(v.iter().map(|x| compile(x, max_repeat)).collect::<Result<_, _>>()?),
        HirKind::Alternation(v) => Node::Alt(v.iter().map(|x| compile(x, max_repeat)).collect::<Result<_, _>>()?),
    })
}

impl RandRegex {
    pub fn compile(pattern: &str, max_repeat: u32) -> Result<RandRegex, RegexError> {
        let hir = regex_syntax::ParserBuilder::new()
            .build()
            .parse(pattern)
            .map_err(|e| RegexError::Syntax(Box::new(e)))?;
        Ok(RandRegex { root: compile(&hir, max_repeat)? })
    }

    pub fn generate<R: Rng>(&self, rng: &mut R) -> String {
        let mut out = Vec::new();
        gen(&self.root, rng, &mut out);
        String::from_utf8_lossy(&out).into_owned()
    }
}

fn gen<R: Rng>(n: &Node, rng: &mut R, out: &mut Vec<u8>) {
    match n {
        Node::Literal(b) => out.extend_from_slice(b),
        Node::Unicode(ranges, total) => {
            let mut k = rng.gen_range(0..*total);
            for (a, b) in ranges {
                let size = (*b - *a + 1) as u64;
                if k < size {
                    let c = char::from_u32(*a + k as u32).unwrap_or('\u{FFFD}');
                    let mut buf = [0u8; 4];
                    out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
                    return;
                }
                k -= size;
            }
        }
        Node::Bytes(ranges, total) => {
            let mut k = rng.gen_range(0..*total);
            for (a, b) in ranges {
                let size = *b as u64 - *a as u64 + 1;
                if k < size {
                    out.push(*a + k as u8);
                    return;
                }
                k -= size;
            }
        }
        Node::Repeat(sub, min, max) => {
            let count = if max <= min { *min } else { rng.gen_range(*min..=*max) };
            for _ in 0..count {
                gen(sub, rng, out);
            }
        }
        Node::Concat(v) => {
            for x in v {
                gen(x, rng, out);
            }
        }
        Node::Alt(v) => {
            let i = rng.gen_range(0..v.len());
            gen(&v[i], rng, out);
        }
    }
}
