actions.command:
cat > /workspace/src/client.rs <<'EOF'
//! HTTP client logic shared by all workers.

use crate::aws::AwsSigner;
use crate::cli::ConnectTo;
use crate::dns::{self, Strategy};
use crate::http1::{H1Conn, H1Error, Response};
use crate::net::{self, Conn, Limits, NetError, Transport};
use crate::tls::TlsContext;
use crate::urlgen::UrlGenerator;
use rand::rngs::StdRng;
use rand::Rng;
use std::collections::HashMap;
use std::net::IpAddr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use url::Url;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum HttpVersion {
    V09,
    V10,
    V11,
    V2,
}

pub enum BodySource {
    None,
    Static(Arc<Vec<u8>>),
    Lines(Vec<Arc<Vec<u8>>>),
}

#[derive(Clone, Copy, Debug)]
pub struct ConnectionTime {
    pub dns_lookup: Instant,
    pub dialup: Instant,
}

#[derive(Clone, Debug)]
pub struct RequestResult {
    pub start_latency_correction: Option<Instant>,
    pub start: Instant,
    pub connection_time: Option<ConnectionTime>,
    pub first_byte: Option<Instant>,
    pub end: Instant,
    pub status: u16,
    pub len_bytes: usize,
    pub url_path: String,
}

impl RequestResult {
    pub fn duration(&self) -> Duration {
        self.end - self.start_latency_correction.unwrap_or(self.start)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ClientError {
    Deadline,
    Timeout,
    Other(String),
}

impl ClientError {
    pub fn message(&self) -> String {
        match self {
            ClientError::Deadline => "aborted due to deadline".to_string(),
            ClientError::Timeout => "timeout".to_string(),
            ClientError::Other(s) => s.clone(),
        }
    }
}

pub type WorkResult = Result<RequestResult, ClientError>;

fn net_to_client(e: NetError) -> ClientError {
    match e {
        NetError::Timeout => ClientError::Timeout,
        NetError::Aborted => ClientError::Deadline,
        NetError::Eof => ClientError::Other("connection closed before message completed".to_string()),
        NetError::Io(s, _) => ClientError::Other(s),
        NetError::Tls(s) => ClientError::Other(s),
    }
}

fn h1_to_client(e: H1Error) -> ClientError {
    match e {
        H1Error::Net(NetError::Timeout) => ClientError::Timeout,
        H1Error::Net(NetError::Aborted) => ClientError::Deadline,
        other => ClientError::Other(other.message()),
    }
}

pub struct Client {
    pub method: String,
    pub url_gen: UrlGenerator,
    pub headers: Vec<(String, String)>,
    pub body: BodySource,
    pub version: HttpVersion,
    pub proxy: Option<Url>,
    pub proxy_headers: Vec<(String, String)>,
    pub proxy_version: HttpVersion,
    pub redirect_limit: usize,
    pub disable_keepalive: bool,
    pub timeout: Option<Duration>,
    pub connect_timeout: Duration,
    pub strategy: Strategy,
    pub dns_cache: Mutex<HashMap<String, Vec<IpAddr>>>,
    pub pre_lookup: bool,
    pub connect_to: Vec<ConnectTo>,
    pub tls: Option<Arc<TlsContext>>,
    pub tls_h2: Option<Arc<TlsContext>>,
    pub unix_socket: Option<String>,
    pub aws: Option<AwsSigner>,
    pub deadline: Option<Instant>,
}

/// A prepared request.
pub struct PreparedRequest {
    pub url: Url,
    pub method: String,
    pub target: String,
    pub headers: Vec<(String, String)>,
    pub body: Arc<Vec<u8>>,
    pub version: HttpVersion,
}

pub fn insert_header(headers: &mut Vec<(String, String)>, name: &str, value: String) {
    if let Some(h) = headers.iter_mut().find(|(k, _)| k == name) {
        h.1 = value;
    } else {
        headers.push((name.to_string(), value));
    }
}

pub fn authority(url: &Url) -> String {
    url[url::Position::BeforeUsername..url::Position::AfterPort].to_string()
}

pub fn path_and_query(url: &Url) -> String {
    let s = &url[url::Position::BeforePath..url::Position::AfterQuery];
    if s.is_empty() {
        "/".to_string()
    } else {
        s.to_string()
    }
}

pub struct H1State {
    pub conn: Option<H1Conn>,
}

impl Client {
    pub fn is_https(url: &Url) -> bool {
        url.scheme() == "https"
    }

    pub fn body_for_request(&self, rng: &mut StdRng) -> Arc<Vec<u8>> {
        match &self.body {
            BodySource::None => Arc::new(Vec::new()),
            BodySource::Static(b) => b.clone(),
            BodySource::Lines(lines) => lines[rng.gen_range(0..lines.len())].clone(),
        }
    }

    pub fn prepare(&self, url: Url, body: Arc<Vec<u8>>) -> PreparedRequest {
        let use_http_proxy = self.proxy.is_some() && !Self::is_https(&url);
        let target = if use_http_proxy {
            let mut u = url.clone();
            u.set_fragment(None);
            u.to_string()
        } else {
            path_and_query(&url)
        };
        let mut headers = self.headers.clone();
        if use_http_proxy {
            for (k, v) in &self.proxy_headers {
                insert_header(&mut headers, k, v.clone());
            }
        }
        if let Some(aws) = &self.aws {
            headers = self.aws_headers(aws, &url, headers, &body);
        } else if !headers.iter().any(|(k, _)| k == "host") {
            headers.push(("host".to_string(), authority(&url)));
        }
        PreparedRequest {
            url,
            method: self.method.clone(),
            target,
            headers,
            body,
            version: self.version,
        }
    }

    fn aws_headers(&self, aws: &AwsSigner, url: &Url, headers: Vec<(String, String)>, body: &[u8]) -> Vec<(String, String)> {
        let unsigned = ["accept", "accept-encoding", "user-agent", "connection", "authorization"];
        let amz_date = chrono::Utc::now().format("%Y%m%dT%H%M%SZ").to_string();
        let host = url.host_str().unwrap_or("").to_string();
        let mut signed: Vec<(String, String)> = Vec::new();
        let host_given = headers.iter().any(|(k, _)| k == "host");
        if !host_given {
            signed.push(("host".to_string(), host.clone()));
        }
        for (k, v) in &headers {
            if !unsigned.contains(&k.as_str()) {
                if k == "host" {
                    if !signed.iter().any(|(kk, _)| kk == "x-amz-date") {
                        signed.push(("x-amz-date".to_string(), amz_date.clone()));
                    }
                    signed.push(("host".to_string(), host.clone()));
                } else {
                    signed.push((k.clone(), v.clone()));
                }
            }
        }
        if !signed.iter().any(|(k, _)| k == "x-amz-date") {
            signed.push(("x-amz-date".to_string(), amz_date.clone()));
        }
        if let Some(t) = &aws.session_token {
            signed.push(("x-amz-security-token".to_string(), t.clone()));
        }
        if !signed.iter().any(|(k, _)| k == "content-length") {
            signed.push(("content-length".to_string(), body.len().to_string()));
        }
        let auth = aws.sign(&self.method, url, &signed, body, &amz_date);
        let mut out = signed;
        for (k, v) in &headers {
            if unsigned.contains(&k.as_str()) && k != "authorization" {
                out.push((k.clone(), v.clone()));
            }
        }
        out.push(("authorization".to_string(), auth));
        out
    }

    pub fn serialize_h1(&self, req: &PreparedRequest) -> Vec<u8> {
        let mut out = Vec::with_capacity(256 + req.body.len());
        out.extend_from_slice(req.method.as_bytes());
        out.push(b' ');
        out.extend_from_slice(req.target.as_bytes());
        out.extend_from_slice(match req.version {
            HttpVersion::V10 => b" HTTP/1.0\r\n",
            _ => b" HTTP/1.1\r\n",
        });
        let mut has_len = false;
        for (k, v) in &req.headers {
            if k == "content-length" || k == "transfer-encoding" {
                has_len = true;
            }
            out.extend_from_slice(k.as_bytes());
            out.extend_from_slice(b": ");
            out.extend_from_slice(v.as_bytes());
            out.extend_from_slice(b"\r\n");
        }
        if !has_len && !req.body.is_empty() {
            out.extend_from_slice(format!("content-length: {}\r\n", req.body.len()).as_bytes());
        }
        out.extend_from_slice(b"\r\n");
        out.extend_from_slice(&req.body);
        out
    }

    /// Map host/port through --connect-to.
    pub fn map_target(&self, host: &str, port: u16, rng: &mut StdRng) -> (String, u16) {
        let matches: Vec<&ConnectTo> = self
            .connect_to
            .iter()
            .filter(|c| c.requested_host == host && c.requested_port == port)
            .collect();
        if matches.is_empty() {
            (host.to_string(), port)
        } else {
            let c = matches[rng.gen_range(0..matches.len())];
            (c.target_host.clone(), c.target_port)
        }
    }

    pub fn lookup(&self, host: &str, rng: &mut StdRng) -> Result<IpAddr, ClientError> {
        let key = dns::strip_brackets(host).to_string();
        if let Ok(ip) = key.parse::<IpAddr>() {
            return Ok(ip);
        }
        {
            let cache = self.dns_cache.lock().unwrap();
            if let Some(v) = cache.get(&key) {
                if !v.is_empty() {
                    return Ok(v[rng.gen_range(0..v.len())]);
                }
            }
        }
        let addrs = dns::resolve(&key, self.strategy).map_err(ClientError::Other)?;
        if addrs.is_empty() {
            return Err(ClientError::Other("no record found".to_string()));
        }
        Ok(addrs[rng.gen_range(0..addrs.len())])
    }

    /// Pre lookup the URL host and cache the result.
    pub fn pre_lookup_host(&self, url: &Url, rng: &mut StdRng) -> Result<(), String> {
        let host = url.host_str().unwrap_or("").to_string();
        let port = url.port_or_known_default().unwrap_or(80);
        let (host, _) = self.map_target(&host, port, rng);
        let key = dns::strip_brackets(&host).to_string();
        if key.parse::<IpAddr>().is_ok() {
            return Ok(());
        }
        let addrs = dns::resolve(&key, self.strategy)?;
        self.dns_cache.lock().unwrap().insert(key, addrs);
        Ok(())
    }

    /// Establish a connection for the URL. Returns the connection and its timings.
    pub fn connect(
        &self,
        url: &Url,
        rng: &mut StdRng,
        limits: &Limits,
        want_h2: bool,
    ) -> Result<(Conn, Instant), ClientError> {
        let https = Self::is_https(url);
        if let Some(path) = &self.unix_socket {
            if !https {
                let s = net::unix_connect(path).map_err(net_to_client)?;
                return Ok((Conn::plain(Transport::Unix(s)), Instant::now()));
            }
        }
        let host = url.host_str().ok_or_else(|| ClientError::Other("failed to get host from URL".into()))?.to_string();
        let port = url.port_or_known_default().unwrap_or(80);
        let (thost, tport) = self.map_target(&host, port, rng);
        let (chost, cport) = if let Some(p) = &self.proxy {
            (p.host_str().unwrap_or("").to_string(), p.port_or_known_default().unwrap_or(80))
        } else {
            (thost.clone(), tport)
        };
        let ip = self.lookup(&chost, rng)?;
        let dns_done = Instant::now();
        let tcp = net::tcp_connect(ip, cport, self.connect_timeout, limits).map_err(net_to_client)?;
        let mut conn = Conn::plain(Transport::Tcp(tcp));
        if self.proxy.is_some() && https {
            // CONNECT tunnel
            let mut req = format!("CONNECT {}:{} HTTP/1.1\r\n", host, port).into_bytes();
            for (k, v) in &self.proxy_headers {
                req.extend_from_slice(format!("{}: {}\r\n", k, v).as_bytes());
            }
            req.extend_from_slice(b"\r\n");
            let mut h = H1Conn::new(conn);
            let resp = h.round_trip_connect(&req, limits).map_err(h1_to_client)?;
            if resp / 100 != 2 {
                return Err(ClientError::Other(format!("proxy CONNECT failed: {}", resp)));
            }
            conn = h.conn;
        }
        if https {
            let ctx = if want_h2 { self.tls_h2.clone() } else { self.tls.clone() };
            let ctx = ctx.ok_or_else(|| ClientError::Other("TLS is not configured".into()))?;
            let sni = dns::strip_brackets(&host).to_string();
            conn.start_tls(ctx, &sni, limits).map_err(net_to_client)?;
        }
        Ok((conn, dns_done))
    }

    pub fn limits(&self, start: Instant) -> Limits {
        Limits {
            timeout: self.timeout.map(|t| start + t),
            deadline: self.deadline,
            abortable: true,
        }
    }

    /// Perform one HTTP/1 request (with redirects) on the worker state.
    pub fn work_h1(
        &self,
        state: &mut H1State,
        rng: &mut StdRng,
        start_latency_correction: Option<Instant>,
    ) -> WorkResult {
        let start = Instant::now();
        let limits = self.limits(start);
        let url = self.url_gen.generate(rng).map_err(ClientError::Other)?;
        let body = self.body_for_request(rng);
        let mut connection_time = None;
        let reuse = match state.conn.as_mut() {
            Some(c) => !c.is_stale(),
            None => false,
        };
        if !reuse {
            state.conn = None;
            let (conn, dns_done) = self.connect(&url, rng, &limits, false)?;
            connection_time = Some(ConnectionTime { dns_lookup: dns_done, dialup: Instant::now() });
            state.conn = Some(H1Conn::new(conn));
        }
        let req = self.prepare(url.clone(), body.clone());
        let bytes = self.serialize_h1(&req);
        let is_head = self.method.eq_ignore_ascii_case("HEAD");
        let close = self.disable_keepalive;
        let h = state.conn.as_mut().unwrap();
        let resp = match h.round_trip(&bytes, is_head, close, false, &limits) {
            Ok(r) => r,
            Err(e) => {
                state.conn = None;
                return Err(h1_to_client(e));
            }
        };
        let first_byte = resp.first_byte;
        if !resp.keep_alive {
            state.conn = None;
        }
        let resp = self.follow_redirects(state, rng, url.clone(), body, resp, &limits)?;
        let end = Instant::now();
        Ok(RequestResult {
            start_latency_correction,
            start,
            connection_time,
            first_byte: Some(first_byte),
            end,
            status: resp.head.status,
            len_bytes: resp.body_len,
            url_path: path_and_query(&url),
        })
    }

    fn follow_redirects(
        &self,
        state: &mut H1State,
        rng: &mut StdRng,
        mut base: Url,
        body: Arc<Vec<u8>>,
        mut resp: Response,
        limits: &Limits,
    ) -> Result<Response, ClientError> {
        if self.redirect_limit == 0 {
            return Ok(resp);
        }
        let mut remaining = self.redirect_limit;
        loop {
            if !(300..400).contains(&resp.head.status) {
                return Ok(resp);
            }
            let loc = match resp.head.header("location") {
                Some(l) => String::from_utf8_lossy(l).to_string(),
                None => return Ok(resp),
            };
            if remaining == 0 {
                return Err(ClientError::Other("Redirection limit has reached".to_string()));
            }
            remaining -= 1;
            let next = match Url::parse(&loc) {
                Ok(u) => u,
                Err(url::ParseError::RelativeUrlWithoutBase) => base.join(&loc).map_err(|e| ClientError::Other(e.to_string()))?,
                Err(e) => return Err(ClientError::Other(e.to_string())),
            };
            let same = authority(&base) == authority(&next) && base.scheme() == next.scheme();
            let req = self.prepare(next.clone(), body.clone());
            let bytes = self.serialize_h1(&req);
            let is_head = self.method.eq_ignore_ascii_case("HEAD");
            let close = self.disable_keepalive;
            if same && state.conn.is_some() && !state.conn.as_mut().unwrap().is_stale() {
                let h = state.conn.as_mut().unwrap();
                resp = match h.round_trip(&bytes, is_head, close, false, limits) {
                    Ok(r) => r,
                    Err(e) => {
                        state.conn = None;
                        return Err(h1_to_client(e));
                    }
                };
                if !resp.keep_alive {
                    state.conn = None;
                }
            } else if same {
                let (conn, _) = self.connect(&next, rng, limits, false)?;
                let mut h = H1Conn::new(conn);
                resp = h.round_trip(&bytes, is_head, close, false, limits).map_err(h1_to_client)?;
                if resp.keep_alive {
                    state.conn = Some(h);
                }
            } else {
                let (conn, _) = self.connect(&next, rng, limits, false)?;
                let mut h = H1Conn::new(conn);
                resp = h.round_trip(&bytes, is_head, close, false, limits).map_err(h1_to_client)?;
            }
            base = next;
        }
    }
}
EOF
echo ok

