//! Minimal ordered JSON value with serde_json compatible pretty printing.

pub enum J {
    Null,
    F(f64),
    U(u64),
    S(String),
    Obj(Vec<(String, J)>),
}

pub fn f(v: f64) -> J {
    if v.is_finite() {
        J::F(v)
    } else {
        J::Null
    }
}

pub fn opt_f(v: Option<f64>) -> J {
    match v {
        Some(x) => f(x),
        None => J::Null,
    }
}

fn esc(s: &str, out: &mut String) {
    out.push_str(&serde_json::to_string(s).unwrap());
}

fn fmt_f64(v: f64) -> String {
    serde_json::to_string(&v).unwrap()
}

impl J {
    pub fn pretty(&self) -> String {
        let mut s = String::new();
        self.write(&mut s, 0);
        s
    }

    fn write(&self, out: &mut String, indent: usize) {
        match self {
            J::Null => out.push_str("null"),
            J::F(v) => out.push_str(&fmt_f64(*v)),
            J::U(v) => out.push_str(&v.to_string()),
            J::S(s) => esc(s, out),
            J::Obj(items) => {
                if items.is_empty() {
                    out.push_str("{}");
                    return;
                }
                out.push_str("{\n");
                for (i, (k, v)) in items.iter().enumerate() {
                    for _ in 0..indent + 1 {
                        out.push_str("  ");
                    }
                    esc(k, out);
                    out.push_str(": ");
                    v.write(out, indent + 1);
                    if i + 1 < items.len() {
                        out.push(',');
                    }
                    out.push('\n');
                }
                for _ in 0..indent {
                    out.push_str("  ");
                }
                out.push('}');
            }
        }
    }
}

/// Insert with map semantics (replace value of existing key, keep position).
pub fn map_insert(items: &mut Vec<(String, J)>, k: String, v: J) {
    if let Some(e) = items.iter_mut().find(|(kk, _)| *kk == k) {
        e.1 = v;
    } else {
        items.push((k, v));
    }
}
EOF
