actions.command:
cat > /workspace/src/printer.rs <<'EOF'
//! Final report printing (text / json / csv / quiet).

use crate::cli::{OutputFormat, TimeUnit};
use crate::client::RequestResult;
use crate::jsonw::{self, J};
use crossterm::style::{Color, Stylize};
use std::collections::BTreeMap;
use std::collections::HashMap;
use std::io::Write;
use std::time::{Duration, Instant};

pub struct Report<'a> {
    pub start: Instant,
    pub total: Duration,
    pub success: &'a [RequestResult],
    pub errors: &'a [(String, usize)],
    pub deadline_errors: usize,
    pub stats_success_breakdown: bool,
}

pub const PERCENTILES: [f64; 9] = [10.0, 25.0, 50.0, 75.0, 90.0, 95.0, 99.0, 99.9, 99.99];

pub fn percentile_of_sorted(sorted: &[f64], p: f64) -> Option<f64> {
    if sorted.is_empty() {
        return None;
    }
    let idx = (sorted.len() as f64 * p / 100.0) as usize;
    Some(sorted[idx.min(sorted.len() - 1)])
}

/// hey style histogram: `bins` buckets from fastest to slowest.
pub fn histogram(values: &[f64], bins: usize) -> Vec<(f64, usize)> {
    let mut sorted = values.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let fastest = sorted.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = sorted.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let bc = bins.saturating_sub(1).max(1);
    let bs = (slowest - fastest) / bc as f64;
    let mut buckets: Vec<f64> = (0..bins).map(|i| fastest + bs * i as f64).collect();
    if bins == 0 {
        return Vec::new();
    }
    let _ = &mut buckets;
    let mut counts = vec![0usize; bins];
    let mut bi = 0;
    let mut i = 0;
    while i < sorted.len() {
        if sorted[i] <= buckets[bi] {
            i += 1;
            counts[bi] += 1;
        } else if bi < bins - 1 {
            bi += 1;
        } else {
            // should not happen; put into last
            counts[bi] += 1;
            i += 1;
        }
    }
    buckets.into_iter().zip(counts).collect()
}

fn auto_unit(slowest: f64) -> TimeUnit {
    if slowest >= 3600.0 {
        TimeUnit::H
    } else if slowest >= 60.0 {
        TimeUnit::M
    } else if slowest >= 1.0 {
        TimeUnit::S
    } else if slowest >= 1e-3 {
        TimeUnit::Ms
    } else if slowest >= 1e-6 {
        TimeUnit::Us
    } else {
        TimeUnit::Ns
    }
}

fn unit_conv(u: TimeUnit, secs: f64) -> f64 {
    match u {
        TimeUnit::Ns => secs * 1e9,
        TimeUnit::Us => secs * 1e6,
        TimeUnit::Ms => secs * 1e3,
        TimeUnit::S => secs,
        TimeUnit::M => secs / 60.0,
        TimeUnit::H => secs / 3600.0,
    }
}

fn unit_label(u: TimeUnit) -> &'static str {
    match u {
        TimeUnit::Ns => "ns",
        TimeUnit::Us => "us",
        TimeUnit::Ms => "ms",
        TimeUnit::S => "sec",
        TimeUnit::M => "min",
        TimeUnit::H => "hr",
    }
}

pub fn format_bytes(n: u64) -> String {
    if n < 1024 {
        return format!("{} B", n);
    }
    let units = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    let mut v = n as f64 / 1024.0;
    let mut i = 0;
    while v >= 1024.0 && i < units.len() - 1 {
        v /= 1024.0;
        i += 1;
    }
    format!("{:.2} {}", v, units[i])
}

fn latency_color(secs: f64) -> Color {
    if secs < 0.1 {
        Color::Green
    } else if secs < 0.4 {
        Color::Yellow
    } else {
        Color::Red
    }
}

fn status_color(code: u16) -> Color {
    match code / 100 {
        2 => Color::Green,
        4 => Color::Yellow,
        5 => Color::Red,
        _ => Color::White,
    }
}

pub struct Stats {
    pub durations: Vec<f64>,
}

fn min_max_avg(v: &[f64]) -> (f64, f64, f64) {
    let fastest = v.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = v.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let avg = v.iter().sum::<f64>() / v.len() as f64;
    (avg, fastest, slowest)
}

pub fn rps_samples(report: &Report) -> Vec<f64> {
    let mut ends: Vec<f64> = report.success.iter().map(|r| (r.end - report.start).as_secs_f64()).collect();
    ends.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let mut out = Vec::new();
    let mut last = 0.0;
    let mut count = 0usize;
    let mut prev: Option<f64> = None;
    for e in ends {
        if let Some(p) = prev {
            if e - last > 0.01 && count > 0 {
                out.push(count as f64 / (p - last));
                last = p;
                count = 0;
            }
        }
        count += 1;
        prev = Some(e);
    }
    if let Some(p) = prev {
        if count > 0 {
            out.push(count as f64 / (p - last));
        }
    }
    out
}

struct Common {
    durations: Vec<f64>,
    success_count: usize,
    total_requests: usize,
    success_rate: f64,
    total: f64,
    slowest: f64,
    fastest: f64,
    average: f64,
    rps: f64,
    total_data: u64,
    size_per_request: Option<u64>,
    size_per_sec: f64,
    dialup: Vec<f64>,
    dns: Vec<f64>,
    status: Vec<(u16, usize)>,
}

fn common(r: &Report) -> Common {
    let durations: Vec<f64> = r.success.iter().map(|x| x.duration().as_secs_f64()).collect();
    let success_count = r.success.len();
    let err_total: usize = r.errors.iter().map(|(_, c)| *c).sum();
    let total_requests = success_count + err_total;
    let denom = success_count + err_total - r.deadline_errors;
    let success_rate = success_count as f64 / denom as f64;
    let total = r.total.as_secs_f64();
    let (average, fastest, slowest) = min_max_avg(&durations);
    let total_data: u64 = r.success.iter().map(|x| x.len_bytes as u64).sum();
    let size_per_request = if success_count > 0 { Some(total_data / success_count as u64) } else { None };
    let mut dialup = Vec::new();
    let mut dns = Vec::new();
    for x in r.success {
        if let Some(c) = x.connection_time {
            dialup.push((c.dialup - x.start).as_secs_f64());
            dns.push((c.dns_lookup - x.start).as_secs_f64());
        }
    }
    let mut map: HashMap<u16, usize> = HashMap::new();
    for x in r.success {
        *map.entry(x.status).or_default() += 1;
    }
    let mut status: Vec<(u16, usize)> = map.into_iter().collect();
    status.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    Common {
        durations,
        success_count,
        total_requests,
        success_rate,
        total,
        slowest,
        fastest,
        average,
        rps: total_requests as f64 / total,
        total_data,
        size_per_request,
        size_per_sec: total_data as f64 / total,
        dialup,
        dns,
        status,
    }
}

pub fn print_report(
    w: &mut dyn Write,
    report: &Report,
    format: OutputFormat,
    time_unit: Option<TimeUnit>,
    color: bool,
) -> std::io::Result<()> {
    match format {
        OutputFormat::Quiet => Ok(()),
        OutputFormat::Text => print_text(w, report, time_unit, color),
        OutputFormat::Json => print_json(w, report),
        OutputFormat::Csv => print_csv(w, report),
    }
}

fn print_csv(w: &mut dyn Write, r: &Report) -> std::io::Result<()> {
    writeln!(w, "request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status")?;
    let mut v: Vec<&RequestResult> = r.success.iter().collect();
    v.sort_by_key(|x| x.start);
    for x in v {
        let (dns, dial) = match x.connection_time {
            Some(c) => ((c.dns_lookup - x.start).as_secs_f64(), (c.dialup - x.start).as_secs_f64()),
            None => (0.0, 0.0),
        };
        let fb = x.first_byte.map(|f| (f - x.start).as_secs_f64()).unwrap_or(0.0);
        writeln!(
            w,
            "{},{},{},{},{},{},{}",
            (x.start - r.start).as_secs_f64(),
            dns,
            dial,
            fb,
            x.duration().as_secs_f64(),
            x.len_bytes,
            x.status
        )?;
    }
    Ok(())
}

fn hist_json(values: &[f64]) -> J {
    let h = histogram(values, 11);
    let mut m: BTreeMap<String, usize> = BTreeMap::new();
    for (k, c) in h {
        m.insert(format!("{}", k), c);
    }
    J::Obj(m.into_iter().map(|(k, v)| (k, J::U(v as u64))).collect())
}

fn pct_json(values: &[f64]) -> J {
    let mut sorted = values.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let names = ["p10", "p25", "p50", "p75", "p90", "p95", "p99", "p99.9", "p99.99"];
    J::Obj(
        PERCENTILES
            .iter()
            .zip(names.iter())
            .map(|(p, n)| (n.to_string(), jsonw::opt_f(percentile_of_sorted(&sorted, *p))))
            .collect(),
    )
}

fn split_success(r: &Report) -> (Vec<f64>, Vec<f64>) {
    let mut ok = Vec::new();
    let mut bad = Vec::new();
    for x in r.success {
        let d = x.duration().as_secs_f64();
        if (200..300).contains(&x.status) {
            ok.push(d);
        } else {
            bad.push(d);
        }
    }
    (ok, bad)
}

fn mmavg_json(v: &[f64]) -> J {
    if v.is_empty() {
        return J::Obj(vec![
            ("average".into(), J::Null),
            ("fastest".into(), J::Null),
            ("slowest".into(), J::Null),
        ]);
    }
    let (a, f, s) = min_max_avg(v);
    J::Obj(vec![
        ("average".into(), jsonw::f(a)),
        ("fastest".into(), jsonw::f(f)),
        ("slowest".into(), jsonw::f(s)),
    ])
}

fn print_json(w: &mut dyn Write, r: &Report) -> std::io::Result<()> {
    let c = common(r);
    let mut top: Vec<(String, J)> = Vec::new();
    top.push((
        "summary".into(),
        J::Obj(vec![
            ("successRate".into(), jsonw::f(c.success_rate)),
            ("total".into(), jsonw::f(c.total)),
            ("slowest".into(), jsonw::f(c.slowest)),
            ("fastest".into(), jsonw::f(c.fastest)),
            ("average".into(), jsonw::f(c.average)),
            ("requestsPerSec".into(), jsonw::f(c.rps)),
            ("totalData".into(), J::U(c.total_data)),
            ("sizePerRequest".into(), match c.size_per_request {
                Some(v) => J::U(v),
                None => J::Null,
            }),
            ("sizePerSec".into(), jsonw::f(c.size_per_sec)),
        ]),
    ));
    top.push(("responseTimeHistogram".into(), hist_json(&c.durations)));
    top.push(("latencyPercentiles".into(), pct_json(&c.durations)));
    if r.stats_success_breakdown {
        let (ok, bad) = split_success(r);
        top.push(("responseTimeHistogramSuccessful".into(), hist_json(&ok)));
        top.push(("latencyPercentilesSuccessful".into(), pct_json(&ok)));
        top.push(("responseTimeHistogramNotSuccessful".into(), hist_json(&bad)));
        top.push(("latencyPercentilesNotSuccessful".into(), pct_json(&bad)));
    }
    let samples = rps_samples(r);
    let mut sorted = samples.clone();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let n = samples.len();
    let mean = if n > 0 { Some(samples.iter().sum::<f64>() / n as f64) } else { None };
    let stddev = if n > 1 {
        let m = mean.unwrap();
        Some((samples.iter().map(|x| (x - m) * (x - m)).sum::<f64>() / (n - 1) as f64).sqrt())
    } else {
        None
    };
    let max = sorted.last().cloned();
    let min = sorted.first().cloned();
    top.push((
        "rps".into(),
        J::Obj(vec![
            ("mean".into(), jsonw::opt_f(mean)),
            ("stddev".into(), jsonw::opt_f(stddev)),
            ("max".into(), jsonw::opt_f(max)),
            ("min".into(), jsonw::opt_f(min)),
            ("percentiles".into(), pct_json(&samples)),
        ]),
    ));
    top.push((
        "details".into(),
        J::Obj(vec![("DNSDialup".into(), mmavg_json(&c.dialup)), ("DNSLookup".into(), mmavg_json(&c.dns))]),
    ));
    let mut sc: BTreeMap<String, usize> = BTreeMap::new();
    for (k, v) in &c.status {
        sc.insert(k.to_string(), *v);
    }
    top.push(("statusCodeDistribution".into(), J::Obj(sc.into_iter().map(|(k, v)| (k, J::U(v as u64))).collect())));
    let mut ed: BTreeMap<String, usize> = BTreeMap::new();
    for (k, v) in r.errors {
        *ed.entry(k.clone()).or_default() += *v;
    }
    top.push(("errorDistribution".into(), J::Obj(ed.into_iter().map(|(k, v)| (k, J::U(v as u64))).collect())));
    let s = J::Obj(top).pretty();
    w.write_all(s.as_bytes())?;
    Ok(())
}

fn styled(color: bool, s: String, fg: Option<Color>, bold: bool, underline: bool) -> String {
    if !color {
        return s;
    }
    let mut st = s.stylize();
    if let Some(c) = fg {
        st = st.with(c);
    }
    if bold {
        st = st.bold();
    }
    if underline {
        st = st.underlined();
    }
    format!("{}", st)
}

fn heading(color: bool, s: &str) -> String {
    styled(color, s.to_string(), None, true, true)
}

fn print_histogram(w: &mut dyn Write, values: &[f64], unit: TimeUnit, color: bool) -> std::io::Result<()> {
    let h = histogram(values, 11);
    let max_count = h.iter().map(|x| x.1).max().unwrap_or(0);
    let count_w = max_count.to_string().len();
    let label_w = h
        .iter()
        .map(|(l, _)| (unit_conv(unit, *l) as u64).to_string().len())
        .max()
        .unwrap_or(1)
        + 4;
    for (label, count) in &h {
        let bar = if max_count > 0 { count * 32 / max_count } else { 0 };
        let pad = " ".repeat(count_w - count.to_string().len());
        let text = format!(
            "  {:>width$.3} {} [{}]{} |",
            unit_conv(unit, *label),
            unit_label(unit),
            count,
            pad,
            width = label_w
        );
        if color {
            let c = latency_color(*label);
            let mut line = format!("{}", text.with(c));
            for _ in 0..bar {
                line.push_str(&format!("{}", "■".with(c)));
            }
            writeln!(w, "{}", line)?;
        } else {
            writeln!(w, "{}{}", text, "■".repeat(bar))?;
        }
    }
    Ok(())
}

fn print_distribution(w: &mut dyn Write, values: &[f64], unit: TimeUnit, color: bool) -> std::io::Result<()> {
    let mut sorted = values.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    for p in PERCENTILES {
        let v = percentile_of_sorted(&sorted, p).unwrap_or(f64::NAN);
        let text = format!("  {:.2}% in {:.4} {}", p, unit_conv(unit, v), unit_label(unit));
        if color {
            writeln!(w, "{}", text.with(latency_color(v)))?;
        } else {
            writeln!(w, "{}", text)?;
        }
    }
    Ok(())
}

fn print_text(w: &mut dyn Write, r: &Report, time_unit: Option<TimeUnit>, color: bool) -> std::io::Result<()> {
    let c = common(r);
    let unit = time_unit.unwrap_or_else(|| auto_unit(c.slowest));
    let ul = unit_label(unit);
    writeln!(w, "{}", heading(color, "Summary:"))?;
    let sr = format!("  Success rate:\t{:.2}%", c.success_rate * 100.0);
    let src = if c.success_rate >= 1.0 { Color::Green } else { Color::Red };
    writeln!(w, "{}", styled(color, sr, Some(src), true, false))?;
    writeln!(w, "  Total:\t{:.4} {}", unit_conv(unit, c.total), ul)?;
    let line = format!("  Slowest:\t{:.4} {}", unit_conv(unit, c.slowest), ul);
    writeln!(w, "{}", styled(color, line, Some(Color::Yellow), false, false))?;
    let line = format!("  Fastest:\t{:.4} {}", unit_conv(unit, c.fastest), ul);
    writeln!(w, "{}", styled(color, line, Some(Color::Green), false, false))?;
    let line = format!("  Average:\t{:.4} {}", unit_conv(unit, c.average), ul);
    writeln!(w, "{}", styled(color, line, Some(Color::Cyan), false, false))?;
    writeln!(w, "  Requests/sec:\t{:.4}", c.rps)?;
    writeln!(w)?;
    writeln!(w, "  Total data:\t{}", format_bytes(c.total_data))?;
    match c.size_per_request {
        Some(v) => writeln!(w, "  Size/request:\t{}", format_bytes(v))?,
        None => writeln!(w, "  Size/request:\tNaN")?,
    }
    writeln!(w, "  Size/sec:\t{}", format_bytes(c.size_per_sec as u64))?;
    writeln!(w)?;
    writeln!(w, "{}", heading(color, "Response time histogram:"))?;
    print_histogram(w, &c.durations, unit, color)?;
    writeln!(w)?;
    writeln!(w, "{}", heading(color, "Response time distribution:"))?;
    print_distribution(w, &c.durations, unit, color)?;
    writeln!(w)?;
    if r.stats_success_breakdown {
        let (ok, bad) = split_success(r);
        writeln!(w, "{}", heading(color, "Response time histogram (2xx only):"))?;
        print_histogram(w, &ok, unit, color)?;
        writeln!(w)?;
        writeln!(w, "{}", heading(color, "Response time distribution (2xx only):"))?;
        print_distribution(w, &ok, unit, color)?;
        writeln!(w)?;
        writeln!(w, "{}", heading(color, "Response time histogram (4xx + 5xx only):"))?;
        print_histogram(w, &bad, unit, color)?;
        writeln!(w)?;
        writeln!(w, "{}", heading(color, "Response time distribution (4xx + 5xx only):"))?;
        print_distribution(w, &bad, unit, color)?;
        writeln!(w)?;
    }
    writeln!(w)?;
    writeln!(w, "{}", heading(color, "Details (average, fastest, slowest):"))?;
    let (a, f, s) = min_max_avg(&c.dialup);
    writeln!(
        w,
        "  DNS+dialup:\t{:.4} {}, {:.4} {}, {:.4} {}",
        unit_conv(unit, a),
        ul,
        unit_conv(unit, f),
        ul,
        unit_conv(unit, s),
        ul
    )?;
    let (a, f, s) = min_max_avg(&c.dns);
    writeln!(
        w,
        "  DNS-lookup:\t{:.4} {}, {:.4} {}, {:.4} {}",
        unit_conv(unit, a),
        ul,
        unit_conv(unit, f),
        ul,
        unit_conv(unit, s),
        ul
    )?;
    writeln!(w)?;
    writeln!(w, "{}", heading(color, "Status code distribution:"))?;
    for (code, count) in &c.status {
        let line = format!("  [{}] {} responses", code, count);
        writeln!(w, "{}", styled(color, line, Some(status_color(*code)), false, false))?;
    }
    if !r.errors.is_empty() {
        writeln!(w)?;
        writeln!(w, "Error distribution:")?;
        let mut errs: Vec<(String, usize)> = r.errors.to_vec();
        errs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
        for (e, n) in errs {
            writeln!(w, "  [{}] {}", n, e)?;
        }
    }
    let _ = c.success_count;
    Ok(())
}
