    fn sqlite3_bind_double(s: *mut Stmt, i: c_int, v: f64) -> c_int;
    fn sqlite3_bind_int64(s: *mut Stmt, i: c_int, v: i64) -> c_int;
    fn sqlite3_bind_null(s: *mut Stmt, i: c_int) -> c_int;
    fn sqlite3_step(s: *mut Stmt) -> c_int;
    fn sqlite3_reset(s: *mut Stmt) -> c_int;
    fn sqlite3_finalize(s: *mut Stmt) -> c_int;
}

const SQLITE_OK: c_int = 0;
const SQLITE_DONE: c_int = 101;
const SQLITE_TRANSIENT: isize = -1;

fn errmsg(db: *mut Sqlite3) -> String {
    unsafe { CStr::from_ptr(sqlite3_errmsg(db)).to_string_lossy().into_owned() }
}

fn exec(db: *mut Sqlite3, sql: &str) -> Result<(), String> {
    let c = CString::new(sql).unwrap();
    let r = unsafe { sqlite3_exec(db, c.as_ptr(), std::ptr::null(), std::ptr::null_mut(), std::ptr::null_mut()) };
    if r != SQLITE_OK {
        return Err(errmsg(db));
    }
    Ok(())
}

pub fn store(path: &str, start: Instant, run: i64, results: &[RequestResult]) -> Result<(), String> {
    unsafe {
        let cpath = CString::new(path).map_err(|e| e.to_string())?;
        let mut db: *mut Sqlite3 = std::ptr::null_mut();
        let r = sqlite3_open(cpath.as_ptr(), &mut db);
        if r != SQLITE_OK {
            let msg = if db.is_null() { "unable to open database file".to_string() } else { errmsg(db) };
            if !db.is_null() {
                sqlite3_close(db);
            }
            return Err(format!("{}: {}", msg, path));
        }
        let res = (|| -> Result<(), String> {
            exec(
                db,
                "CREATE TABLE IF NOT EXISTS oha (
            url TEXT NOT NULL,
            start REAL NOT NULL,
            start_latency_correction REAL,
            end REAL NOT NULL,
            duration REAL NOT NULL,
            status INTEGER NOT NULL,
            len_bytes INTEGER NOT NULL,
            run INTEGER NOT NULL
        )",
            )?;
            exec(db, "BEGIN")?;
            let sql = CString::new(
                "INSERT INTO oha (url, start, start_latency_correction, end, duration, status, len_bytes, run) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
            )
            .unwrap();
            let mut stmt: *mut Stmt = std::ptr::null_mut();
            if sqlite3_prepare_v2(db, sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) != SQLITE_OK {
                return Err(errmsg(db));
            }
            for r in results {
                let url = CString::new(r.url_path.clone()).unwrap_or_default();
                sqlite3_bind_text(stmt, 1, url.as_ptr(), -1, SQLITE_TRANSIENT);
                sqlite3_bind_double(stmt, 2, (r.start - start).as_secs_f64());
                match r.start_latency_correction {
                    Some(s) => sqlite3_bind_double(stmt, 3, (s.max(start) - start).as_secs_f64()),
                    None => sqlite3_bind_null(stmt, 3),
                };
                sqlite3_bind_double(stmt, 4, (r.end - start).as_secs_f64());
                sqlite3_bind_double(stmt, 5, r.duration().as_secs_f64());
                sqlite3_bind_int64(stmt, 6, r.status as i64);
                sqlite3_bind_int64(stmt, 7, r.len_bytes as i64);
                sqlite3_bind_int64(stmt, 8, run);
                let s = sqlite3_step(stmt);
                if s != SQLITE_DONE {
                    let e = errmsg(db);
                    sqlite3_finalize(stmt);
                    return Err(e);
                }
                sqlite3_reset(stmt);
            }
            sqlite3_finalize(stmt);
            exec(db, "COMMIT")?;
            Ok(())
        })();
        sqlite3_close(db);
        res
    }
}
