        qps: Option<f64>,
        burst: Option<(Duration, usize)>,
        latency_correction: bool,
        start: Instant,
    ) -> Schedule {
        Schedule { n_requests, deadline, qps, burst, latency_correction, start, next: AtomicU64::new(0) }
    }

    /// Wait for the next ticket. Returns None when no more work.
    /// The returned value is the start used for latency correction.
    pub fn next_ticket(&self) -> Option<Option<Instant>> {
        if ABORT.load(Ordering::Relaxed) {
            return None;
        }
        if let Some(d) = self.deadline {
            if Instant::now() >= d {
                return None;
            }
        }
        let i = self.next.fetch_add(1, Ordering::SeqCst);
        if let Some(n) = self.n_requests {
            if i >= n {
                return None;
            }
        }
        let t = if let Some(q) = self.qps {
            if q > 0.0 && q.is_finite() {
                Some(self.start + Duration::from_secs_f64(i as f64 / q))
            } else {
                None
            }
        } else if let Some((delay, rate)) = self.burst {
            let rate = rate.max(1) as u64;
            Some(self.start + delay * ((i / rate + 1) as u32))
        } else {
            None
        };
        if let Some(t) = t {
            loop {
                if ABORT.load(Ordering::Relaxed) {
                    return None;
                }
                let now = Instant::now();
                if let Some(d) = self.deadline {
                    if now >= d || t >= d {
                        // wait until deadline then stop
                        if t >= d {
                            while Instant::now() < d && !ABORT.load(Ordering::Relaxed) {
                                std::thread::sleep(Duration::from_millis(5).min(d.saturating_duration_since(Instant::now())));
                            }
                            return None;
                        }
                        return None;
                    }
                }
                if now >= t {
                    break;
                }
                std::thread::sleep((t - now).min(Duration::from_millis(20)));
            }
            if self.latency_correction {
                Some(None)
            } else {
                Some(Some(t))
            }
        } else {
            Some(None)
        }
    }
}

/// Run an HTTP/1 worker until the schedule is exhausted.
pub fn h1_worker(client: Arc<Client>, sched: Arc<Schedule>, tx: Sender<WorkResult>, n_mode: bool) {
    let mut rng = StdRng::from_entropy();
    let mut state = H1State { conn: None };
    while let Some(slc) = sched.next_ticket() {
        let r = client.work_h1(&mut state, &mut rng, slc);
        if let Err(ClientError::Deadline) = &r {
            if n_mode || ABORT.load(Ordering::Relaxed) && n_mode {
                continue;
            }
        }
        if tx.send(r).is_err() {
            break;
        }
    }
}
