//! `--debug` request/response dump in the style of Rust's pretty Debug output.

use crate::client::{HttpVersion, PreparedRequest};

pub fn bytes_debug(b: &[u8]) -> String {
    let mut s = String::from("b\"");
    for &c in b {
        match c {
            b'\n' => s.push_str("\\n"),
            b'\r' => s.push_str("\\r"),
            b'\t' => s.push_str("\\t"),
            b'\\' | b'"' => {
                s.push('\\');
                s.push(c as char);
            }
            0 => s.push_str("\\0"),
            0x20..=0x7e => s.push(c as char),
            _ => s.push_str(&format!("\\x{:02x}", c)),
        }
    }
    s.push('"');
    s
}

pub fn header_value_debug(v: &[u8]) -> String {
    let mut s = String::from("\"");
    for &b in v {
        let visible = (32..127).contains(&b) || b == b'\t';
        if !visible || b == b'"' {
            if b == b'"' {
                s.push_str("\\\"");
            } else {
                s.push_str(&format!("\\x{:x}", b));
            }
        } else {
            s.push(b as char);
        }
    }
    s.push('"');
    s
}

