        HttpVersion::V11 => "HTTP/1.1",
        HttpVersion::V2 => "HTTP/2.0",
    }
}

fn headers_debug(out: &mut String, headers: &[(String, Vec<u8>)]) {
    if headers.is_empty() {
        out.push_str("    headers: {},\n");
        return;
