    let mut s = String::from("Request {\n");
    s.push_str(&format!("    method: {},\n", req.method));
    s.push_str(&format!("    uri: {},\n", target));
    s.push_str(&format!("    version: {},\n", version_str(req.version)));
    let hs: Vec<(String, Vec<u8>)> = req.headers.iter().map(|(k, v)| (k.clone(), v.as_bytes().to_vec())).collect();
