        s.push_str("        data: None,\n");
    } else {
        s.push_str("        data: Some(\n");
        s.push_str(&format!("            {},\n", bytes_debug(&req.body)));
        s.push_str("        ),\n");
    }
    s.push_str("    },\n}");
    s
}

pub fn response_debug(status: u16, version: &str, headers: &[(String, Vec<u8>)], body: &[u8]) -> String {
    let mut s = String::from("Response {\n");
    s.push_str(&format!("    status: {},\n", status));
    s.push_str(&format!("    version: {},\n", version));
    headers_debug(&mut s, headers);
    s.push_str(&format!("    body: {},\n", bytes_debug(body)));
    s.push('}');
    s
}
