fn parse_version(s: &str) -> Result<HttpVersion, String> {
    match s.trim() {
        "0.9" => Ok(HttpVersion::V09),
        "1.0" => Ok(HttpVersion::V10),
        "1.1" => Ok(HttpVersion::V11),
        "2" | "2.0" => Ok(HttpVersion::V2),
        "3" | "3.0" => Err("Your Oha instance has not been built with HTTP/3 support. Try recompiling with the feature enabled.".to_string()),
        _ => Err("Unknown HTTP version. Valid versions are 0.9, 1.0, 1.1, 2, 3".to_string()),
    }
}

fn io_msg(e: std::io::Error) -> String {
    e.to_string()
}

fn random_hex(n: usize) -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    (0..n).map(|_| format!("{:x}", rng.gen_range(0..16u8))).collect()
}

fn build_form(forms: &[String]) -> Result<(String, Vec<u8>), String> {
    let boundary = format!("----formdata-oha-{}", random_hex(32));
    let mut body = Vec::new();
    for f in forms {
        let err = || format!("Failed to parse form data: {}", f);
        let (name, rest) = f.split_once('=').ok_or_else(err)?;
        let mut parts = rest.split(';');
        let value = parts.next().unwrap_or("");
        let mut ctype: Option<String> = None;
        let mut filename: Option<String> = None;
        for p in parts {
            if let Some(t) = p.strip_prefix("type=") {
                ctype = Some(t.to_string());
            } else if let Some(fname) = p.strip_prefix("filename=") {
                filename = Some(fname.to_string());
            }
        }
        let (data, fname) = if let Some(path) = value.strip_prefix('@') {
            let d = std::fs::read(path).map_err(|_| err())?;
            let base = std::path::Path::new(path)
                .file_name()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_default();
            (d, Some(filename.clone().unwrap_or(base)))
        } else if let Some(path) = value.strip_prefix('<') {
            let d = std::fs::read(path).map_err(|_| err())?;
            (d, filename.clone())
        } else {
            (value.as_bytes().to_vec(), filename.clone())
        };
        body.extend_from_slice(format!("--{}\r\n", boundary).as_bytes());
        let mut cd = format!("Content-Disposition: form-data; name=\"{}\"", name);
        if let Some(fname) = fname {
            cd.push_str(&format!("; filename=\"{}\"", fname));
        }
        body.extend_from_slice(cd.as_bytes());
        body.extend_from_slice(b"\r\n");
        if let Some(ct) = ctype {
            body.extend_from_slice(format!("Content-Type: {}\r\n", ct).as_bytes());
        }
        body.extend_from_slice(b"\r\n");
        body.extend_from_slice(&data);
        body.extend_from_slice(b"\r\n");
    }
    body.extend_from_slice(format!("--{}--\r\n", boundary).as_bytes());
    Ok((format!("multipart/form-data; boundary={}", boundary), body))
}

fn main() {
    let opts = cli::parse();
    let code = match run(opts) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error: {}", e);
            1
        }
    };
    std::process::exit(code);
}

fn run(opts: cli::Opts) -> Result<i32, String> {
    // AWS configuration
    let mut aws: Option<aws::AwsSigner> = None;
    if let Some(sig) = &opts.aws_sigv4 {
        let auth = opts
            .basic_auth
            .as_ref()
            .ok_or_else(|| "AWS credentials (--auth) required when using --aws-sigv4".to_string())?;
        let creds: Vec<&str> = auth.split(':').collect();
        if creds.len() != 2 {
            return Err("Invalid AWS credentials format. Expected access_key:secret_key".to_string());
        }
        let parts: Vec<&str> = sig.split(':').collect();
        if parts.len() != 4 || parts[0] != "aws" || parts[1] != "amz" {
            return Err("Invalid AWS signing params format. Expected aws:amz:region:service".to_string());
        }
        aws = Some(aws::AwsSigner {
            access_key: creds[0].to_string(),
            secret_key: creds[1].to_string(),
            session_token: opts.aws_session.clone(),
            region: parts[2].to_string(),
            service: parts[3].to_string(),
        });
    }

    // HTTP version
    if opts.http2 && opts.http_version.is_some() {
        return Err("--http2 and --http-version are exclusive".to_string());
    }
    if opts.proxy_http2 && opts.proxy_http_version.is_some() {
        return Err("--http2 and --http-version are exclusive".to_string());
    }
    let version = if opts.http2 {
        HttpVersion::V2
    } else if let Some(v) = &opts.http_version {
        parse_version(v)?
    } else {
        HttpVersion::V11
    };
    let proxy_version = if opts.proxy_http2 {
        HttpVersion::V2
    } else if let Some(v) = &opts.proxy_http_version {
        parse_version(v)?
    } else {
        HttpVersion::V11
    };

    // URL generator
    let url_gen = if opts.rand_regex_url {
        let pattern = opts.url.replace('.', "\\.");
        let r = randregex::RandRegex::compile(&pattern, opts.max_repeat).map_err(|e| e.to_string())?;
        urlgen::UrlGenerator::Regex(r)
    } else if opts.urls_from_file {
        let content = std::fs::read_to_string(&opts.url).map_err(io_msg)?;
        let mut urls = Vec::new();
        for line in content.lines() {
            if line.trim().is_empty() {
