            }
            urls.push(Url::parse(line).map_err(|e| e.to_string())?);
        }
        if urls.is_empty() {
            eprintln!(
                "\nthread 'main' ({}) panicked at src/url_generator.rs:33:9:\nassertion failed: !urls.is_empty()\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
