    } else {
        urlgen::UrlGenerator::Static(Url::parse(&opts.url).map_err(|e| e.to_string())?)
    };

    if let Some(n) = opts.dump_urls {
        let mut rng = rand::thread_rng();
        let stdout = std::io::stdout();
