    }

    // Body
    let mut content_type = opts.content_type.clone();
    let mut method = opts.method.clone();
    let body = if let Some(s) = &opts.body_string {
        BodySource::Static(Arc::new(s.as_bytes().to_vec()))
    } else if let Some(p) = &opts.body_path {
        BodySource::Static(Arc::new(std::fs::read(p).map_err(io_msg)?))
    } else if let Some(p) = &opts.body_path_lines {
