    } else {
        BodySource::None
    };

    // Headers
    let mut headers: Vec<(String, String)> = Vec::new();
    headers.push(("accept".into(), opts.accept_header.clone().unwrap_or_else(|| "*/*".into())));
    if !opts.disable_compression {
        headers.push(("accept-encoding".into(), "gzip, compress, deflate, br".into()));
    }
