    } else {
        dns::Strategy::Ipv4ThenIpv6
    };

    let start_placeholder = Instant::now();
    let deadline_dur = opts.duration;
    let _ = start_placeholder;

    let mut client = Client {
        method,
        url_gen,
        headers,
        body,
        version,
        proxy: opts.proxy.clone(),
        proxy_headers: opts.proxy_headers.clone(),
