            }
        }
    }
    for h in handles {
        let _ = h.join();
    }
    let total = start.elapsed();
    let errors_v: Vec<(String, usize)> = errors.into_iter().collect();
    let report = printer::Report {
        start,
        total,
        success: &success,
        errors: &errors_v,
        deadline_errors,
        stats_success_breakdown: opts.stats_success_breakdown,
    };
    let write_res = if let Some(path) = &opts.output {
        let mut f = std::fs::File::create(path).map_err(io_msg)?;
        printer::print_report(&mut f, &report, opts.output_format, opts.time_unit, false)
    } else {
        let stdout = std::io::stdout();
        let color = !opts.no_color && stdout.is_terminal();
        let mut out = stdout.lock();
        let r = printer::print_report(&mut out, &report, opts.output_format, opts.time_unit, color);
        let _ = out.flush();
        r
    };
    if let Err(e) = write_res {
        return Err(e.to_string());
    }
