        db::store(dbu, start, run_id, &success)?;
    }
    let _ = Duration::from_secs(0);
    Ok(0)
}

fn run_debug(client: &Client) -> Result<i32, String> {
    let mut rng = <rand::rngs::StdRng as rand::SeedableRng>::from_entropy();
    let url = client.url_gen.generate(&mut rng)?;
    let body = client.body_for_request(&mut rng);
    let req = client.prepare(url.clone(), body);
    println!("{}", debug::request_debug(&req, &req.target));
    let limits = net::Limits { timeout: client.timeout.map(|t| Instant::now() + t), deadline: None, abortable: false };
    let (conn, _) = client.connect(&url, &mut rng, &limits, false).map_err(|e| e.message())?;
    let mut h = http1::H1Conn::new(conn);
    let bytes = client.serialize_h1(&req);
    let is_head = client.method.eq_ignore_ascii_case("HEAD");
    let resp = h
        .round_trip(&bytes, is_head, client.disable_keepalive, true, &limits)
        .map_err(|e| match e {
            http1::H1Error::Net(net::NetError::Timeout) => "timeout".to_string(),
            other => other.message(),
        })?;
    let v = if resp.head.version == 10 { "HTTP/1.0" } else { "HTTP/1.1" };
    println!("{}", debug::response_debug(resp.head.status, v, &resp.head.headers, &resp.body));
    Ok(0)
}
