    for _ in 0..n_workers {
        let c = client.clone();
        let s = sched.clone();
        let t = tx.clone();
        handles.push(std::thread::spawn(move || runner::h1_worker(c, s, t, n_mode)));
    }
    drop(tx);

    let mut success: Vec<RequestResult> = Vec::new();
    let mut errors: HashMap<String, usize> = HashMap::new();
    let mut deadline_errors = 0usize;
    for r in rx {
        match r {
            Ok(x) => success.push(x),
            Err(e) => {
                if e == ClientError::Deadline {
                    deadline_errors += 1;
                }
                *errors.entry(e.message()).or_default() += 1;
            }
        }
    }
    for h in handles {
        let _ = h.join();
    }
    let total = start.elapsed();
    let errors_v: Vec<(String, usize)> = errors.into_iter().collect();
    let report = printer::Report {
        start,
        total,
        success: &success,
        errors: &errors_v,
        deadline_errors,
        stats_success_breakdown: opts.stats_success_breakdown,
    };
    let write_res = if let Some(path) = &opts.output {
        let mut f = std::fs::File::create(path).map_err(io_msg)?;
        printer::print_report(&mut f, &report, opts.output_format, opts.time_unit, false)
    } else {
        let stdout = std::io::stdout();
        let color = !opts.no_color && stdout.is_terminal();
        let mut out = stdout.lock();
        let r = printer::print_report(&mut out, &report, opts.output_format, opts.time_unit, color);
        let _ = out.flush();
        r
    };
    if let Err(e) = write_res {
        return Err(e.to_string());
    }
    if let Some(dbu) = &opts.db_url {
        eprintln!("Storing results to {}", dbu);
        let run_id = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0);
        db::store(dbu, start, run_id, &success)?;
    }
    let _ = Duration::from_secs(0);
    Ok(0)
}

fn run_debug(client: &Client) -> Result<i32, String> {
    let mut rng = <rand::rngs::StdRng as rand::SeedableRng>::from_entropy();
    let url = client.url_gen.generate(&mut rng)?;
    let body = client.body_for_request(&mut rng);
    let req = client.prepare(url.clone(), body);
    println!("{}", debug::request_debug(&req, &req.target));
    let limits = net::Limits { timeout: client.timeout.map(|t| Instant::now() + t), deadline: None, abortable: false };
    let (conn, _) = client.connect(&url, &mut rng, &limits, false).map_err(|e| e.message())?;
    let mut h = http1::H1Conn::new(conn);
    let bytes = client.serialize_h1(&req);
    let is_head = client.method.eq_ignore_ascii_case("HEAD");
    let resp = h
        .round_trip(&bytes, is_head, client.disable_keepalive, true, &limits)
        .map_err(|e| match e {
            http1::H1Error::Net(net::NetError::Timeout) => "timeout".to_string(),
            other => other.message(),
        })?;
    let v = if resp.head.version == 10 { "HTTP/1.0" } else { "HTTP/1.1" };
    println!("{}", debug::response_debug(resp.head.status, v, &resp.head.headers, &resp.body));
    Ok(0)
}
