use ratatui::text::{Line, Span};
use ratatui::widgets::{BarChart, Block, Borders, Gauge, Paragraph};
use ratatui::Terminal;
use std::collections::HashMap;
use std::sync::atomic::Ordering;
use std::sync::mpsc::{Receiver, RecvTimeoutError};
use std::time::{Duration, Instant};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum TimeScale {
    Millisecond,
    Second,
    TenSeconds,
    Minute,
    TenMinutes,
    Hour,
}

const SCALES: [TimeScale; 6] = [
    TimeScale::Millisecond,
    TimeScale::Second,
    TimeScale::TenSeconds,
    TimeScale::Minute,
    TimeScale::TenMinutes,
    TimeScale::Hour,
];

impl TimeScale {
    fn as_secs_f64(&self) -> f64 {
        match self {
            TimeScale::Millisecond => 0.001,
            TimeScale::Second => 1.0,
            TimeScale::TenSeconds => 10.0,
            TimeScale::Minute => 60.0,
            TimeScale::TenMinutes => 600.0,
            TimeScale::Hour => 3600.0,
        }
    }
    fn name(&self) -> &'static str {
        match self {
            TimeScale::Millisecond => "ms",
            TimeScale::Second => "sec",
            TimeScale::TenSeconds => "10 sec",
            TimeScale::Minute => "min",
            TimeScale::TenMinutes => "10 min",
            TimeScale::Hour => "hr",
        }
    }
    fn label(&self, i: usize) -> String {
        match self {
            TimeScale::Millisecond => format!("{}ms", i),
            TimeScale::Second => format!("{}s", i),
            TimeScale::TenSeconds => format!("{}s", i * 10),
            TimeScale::Minute => format!("{}m", i),
            TimeScale::TenMinutes => format!("{}m", i * 10),
            TimeScale::Hour => format!("{}h", i),
        }
    }
    fn index(&self) -> usize {
        SCALES.iter().position(|s| s == self).unwrap()
    }
    fn from_elapsed(elapsed: Duration) -> TimeScale {
        let e = elapsed.as_secs_f64();
        let mut r = TimeScale::Millisecond;
        for s in SCALES {
            if s.as_secs_f64() <= e {
                r = s;
            }
        }
        r
    }
}

pub struct MonitorConfig {
    pub start: Instant,
    pub n_requests: Option<u64>,
    pub duration: Option<Duration>,
    pub fps: usize,
    pub n_mode: bool,
}

pub struct Collected {
    pub success: Vec<RequestResult>,
    pub errors: HashMap<String, usize>,
    pub deadline_errors: usize,
}

fn open_files() -> (usize, u64) {
    let n = std::fs::read_dir("/proc/self/fd").map(|d| d.count()).unwrap_or(0);
    let mut rl = libc::rlimit { rlim_cur: 0, rlim_max: 0 };
    unsafe {
        libc::getrlimit(libc::RLIMIT_NOFILE, &mut rl);
    }
    (n.saturating_sub(1), rl.rlim_cur as u64)
}

fn hist(values: &[f64], bins: usize) -> Vec<(f64, u64)> {
    crate::printer::histogram(values, bins).into_iter().map(|(a, b)| (a, b as u64)).collect()
}

pub fn run_monitor(cfg: MonitorConfig, rx: Receiver<WorkResult>) -> Collected {
    let mut col = Collected { success: Vec::new(), errors: HashMap::new(), deadline_errors: 0 };
    let mut stdout = std::io::stdout();
    let tui_ok = enable_raw_mode().is_ok() && execute!(stdout, EnterAlternateScreen).is_ok();
    let backend = CrosstermBackend::new(std::io::stdout());
    let mut terminal = match Terminal::new(backend) {
        Ok(t) => Some(t),
        Err(_) => None,
    };
    if let Some(t) = terminal.as_mut() {
        let _ = t.hide_cursor();
        let _ = t.clear();
    }
    let fps = if cfg.fps == 0 { 16 } else { cfg.fps };
    let frame = Duration::from_secs_f64(1.0 / fps as f64);
    let mut status_dist: HashMap<u16, usize> = HashMap::new();
    let mut error_dist: HashMap<String, usize> = HashMap::new();
    let mut done: u64 = 0;
    let mut timescale_manual: Option<TimeScale> = None;
    let mut next_draw = Instant::now();
    let mut finished = false;
    loop {
        // drain results
        loop {
            match rx.recv_timeout(Duration::from_millis(0)) {
                Ok(r) => {
                    done += 1;
                    match r {
                        Ok(x) => {
                            *status_dist.entry(x.status).or_default() += 1;
                            col.success.push(x);
                        }
                        Err(e) => {
                            if e == ClientError::Deadline {
                                col.deadline_errors += 1;
                            }
                            *error_dist.entry(e.message()).or_default() += 1;
                            *col.errors.entry(e.message()).or_default() += 1;
                        }
                    }
                }
                Err(RecvTimeoutError::Timeout) => break,
                Err(RecvTimeoutError::Disconnected) => {
                    finished = true;
                    break;
                }
            }
        }
        if finished {
            break;
        }
        let now = Instant::now();
        if now >= next_draw {
            next_draw = now + frame;
            if let Some(term) = terminal.as_mut() {
                let elapsed = now - cfg.start;
                let ts = timescale_manual.unwrap_or_else(|| TimeScale::from_elapsed(elapsed));
                let _ = term.draw(|f| {
                    draw(f, &cfg, &col, &status_dist, &error_dist, done, now, ts, timescale_manual.is_none());
                });
            }
        }
        // input
        let wait = next_draw.saturating_duration_since(Instant::now()).min(Duration::from_millis(20));
        if tui_ok && event::poll(wait).unwrap_or(false) {
            if let Ok(Event::Key(k)) = event::read() {
                if k.kind == KeyEventKind::Press || k.kind == KeyEventKind::Repeat {
                    match k.code {
                        KeyCode::Char('c') if k.modifiers.contains(KeyModifiers::CONTROL) => {
                            ABORT.store(true, Ordering::SeqCst);
                        }
                        KeyCode::Char('q') | KeyCode::Esc => {
                            ABORT.store(true, Ordering::SeqCst);
                        }
                        KeyCode::Char('+') => {
                            let cur = timescale_manual.unwrap_or_else(|| TimeScale::from_elapsed(Instant::now() - cfg.start));
                            let i = cur.index();
                            timescale_manual = Some(SCALES[i.saturating_sub(1)]);
                        }
                        KeyCode::Char('-') => {
                            let cur = timescale_manual.unwrap_or_else(|| TimeScale::from_elapsed(Instant::now() - cfg.start));
                            let i = cur.index();
                            timescale_manual = Some(SCALES[(i + 1).min(SCALES.len() - 1)]);
                        }
                        KeyCode::Char('a') => {
                            timescale_manual = None;
                        }
                        _ => {}
                    }
                }
            }
        } else if !tui_ok {
            std::thread::sleep(wait);
        }
    }
    if let Some(mut t) = terminal {
        let _ = t.show_cursor();
    }
    let _ = disable_raw_mode();
    let _ = execute!(std::io::stdout(), LeaveAlternateScreen);
    col
}

#[allow(clippy::too_many_arguments)]
fn draw(
    f: &mut ratatui::Frame,
    cfg: &MonitorConfig,
    col: &Collected,
    status_dist: &HashMap<u16, usize>,
    error_dist: &HashMap<String, usize>,
    done: u64,
    now: Instant,
    ts: TimeScale,
    auto: bool,
) {
    let area = f.area();
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Length(8),
            Constraint::Length(error_dist.len() as u16 + 2),
            Constraint::Fill(1),
        ])
        .split(area);
    let mid = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(rows[1]);
    let bottom = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(rows[3]);

    let elapsed = now - cfg.start;
    // progress
    let (ratio, label) = if let Some(d) = cfg.duration {
        let r = (elapsed.as_secs_f64() / d.as_secs_f64()).clamp(0.0, 1.0);
        (r, format!("{}s / {}s", elapsed.as_secs().min(d.as_secs()), d.as_secs()))
    } else {
        let n = cfg.n_requests.unwrap_or(0);
        let r = if n == 0 { 1.0 } else { (done as f64 / n as f64).clamp(0.0, 1.0) };
        (r, format!("{} / {}", done, n))
    };
    let gauge = Gauge::default()
        .block(Block::default().title("Progress").borders(Borders::ALL))
        .gauge_style(Style::default().fg(Color::Cyan))
        .label(label)
        .ratio(ratio);
    f.render_widget(gauge, rows[0]);

    // last window stats
    let win = ts.as_secs_f64();
    let window: Vec<&RequestResult> = col
        .success
        .iter()
        .rev()
        .take_while(|r| (now.saturating_duration_since(r.end)).as_secs_f64() <= win)
        .collect();
    let durations: Vec<f64> = window.iter().map(|r| r.duration().as_secs_f64()).collect();
    let fastest = durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let average = durations.iter().sum::<f64>() / durations.len() as f64;
    let data: u64 = window.iter().map(|r| r.len_bytes as u64).sum();
    let (nfiles, limit) = open_files();
    let stats_text = vec![
        Line::from(format!("Requests : {}", window.len())),
        Line::from(Span::styled(format!("Slowest: {:.4} secs", slowest), Style::default().fg(Color::Yellow))),
        Line::from(Span::styled(format!("Fastest: {:.4} secs", fastest), Style::default().fg(Color::Green))),
        Line::from(Span::styled(format!("Average: {:.4} secs", average), Style::default().fg(Color::Cyan))),
        Line::from(format!("Data: {}", format_bytes(data))),
        Line::from(format!("Number of open files: {} / {}", nfiles, limit)),
    ];
    let stats = Paragraph::new(stats_text)
        .block(Block::default().title(format!("Stats for last {}", ts.name())).borders(Borders::ALL));
    f.render_widget(stats, mid[0]);

    let mut sd: Vec<(u16, usize)> = status_dist.iter().map(|(k, v)| (*k, *v)).collect();
    sd.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    let status_text: Vec<Line> = sd.iter().map(|(k, v)| Line::from(format!("[{}] {} responses", k, v))).collect();
    let status = Paragraph::new(status_text)
        .block(Block::default().title("Status code distribution").borders(Borders::ALL));
    f.render_widget(status, mid[1]);

    let mut ed: Vec<(&String, &usize)> = error_dist.iter().collect();
    ed.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    let err_text: Vec<Line> = ed.iter().map(|(k, v)| Line::from(format!("[{}] {}", v, k))).collect();
    let errors = Paragraph::new(err_text).block(Block::default().title("Error distribution").borders(Borders::ALL));
    f.render_widget(errors, rows[2]);

    // requests per timescale
    let nbars = 32usize;
    let mut counts = vec![0u64; nbars];
    let k_now = (elapsed.as_secs_f64() / win) as u64;
    for r in col.success.iter().rev() {
        let k = ((r.end.saturating_duration_since(cfg.start)).as_secs_f64() / win) as u64;
        if k > k_now {
            continue;
        }
        let i = (k_now - k) as usize;
        if i >= nbars {
            break;
        }
        counts[i] += 1;
    }
    let labels: Vec<String> = (0..nbars).map(|i| ts.label(i)).collect();
    let bar_data: Vec<(&str, u64)> = labels.iter().map(|s| s.as_str()).zip(counts.iter().cloned()).collect();
    let bar_width = labels.iter().map(|s| s.chars().count()).max().unwrap_or(1) as u16 + 2;
    let title = format!(
        "Requests / past {}{}. press -/+/a to change",
        ts.name(),
        if auto { " (auto)" } else { "" }
    );
    let chart = BarChart::default()
        .block(Block::default().title(title).style(Style::default().fg(Color::Green)).borders(Borders::ALL))
        .data(bar_data.as_slice())
        .bar_width(bar_width);
    f.render_widget(chart, bottom[0]);

    // histogram
    let bins = (bottom[1].width.saturating_sub(2) / 8).max(1) as usize;
    let h = hist(&durations, bins);
    let hlabels: Vec<String> = h.iter().map(|(v, _)| format!("{:.4}", v)).collect();
    let hdata: Vec<(&str, u64)> = hlabels.iter().map(|s| s.as_str()).zip(h.iter().map(|x| x.1)).collect();
    let hchart = BarChart::default()
        .block(
            Block::default()
                .title("Response time histogram")
                .style(Style::default().fg(Color::Yellow))
                .borders(Borders::ALL),
        )
        .data(hdata.as_slice())
        .bar_width(7);
    f.render_widget(hchart, bottom[1]);
}
