package main

import (
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

var reDelay = regexp.MustCompile(`/delay/(\d+)`)
var reStatus = regexp.MustCompile(`/status/(\d+)`)

func main() {
	logf, _ := os.OpenFile(os.Args[2], os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)
	h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		var keys []string
		for k := range r.Header {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		var sb strings.Builder
		fmt.Fprintf(&sb, "===== %s %s %s host=%s\n", r.Proto, r.Method, r.RequestURI, r.Host)
		for _, k := range keys {
			fmt.Fprintf(&sb, "%s: %s\n", strings.ToLower(k), strings.Join(r.Header[k], ","))
		}
		fmt.Fprintf(&sb, "body=%q\n", body)
		logf.WriteString(sb.String())
		if m := reDelay.FindStringSubmatch(r.URL.Path); m != nil {
			ms, _ := strconv.Atoi(m[1])
			time.Sleep(time.Duration(ms) * time.Millisecond)
		}
		status := 200
		if m := reStatus.FindStringSubmatch(r.URL.Path); m != nil {
			status, _ = strconv.Atoi(m[1])
		}
		w.Header().Set("X-Test", "h2")
		w.WriteHeader(status)
		w.Write([]byte("hello h2"))
	})
	srv := &http.Server{Addr: os.Args[1], Handler: h}
	log.Fatal(srv.ListenAndServeTLS("/tmp/t/cert.pem", "/tmp/t/key.pem"))
}
