struct HuffNode {
    children: [i32; 2],
    sym: i32,
}

pub struct HuffTree {
    nodes: Vec<HuffNode>,
}

impl HuffTree {
    pub fn new() -> HuffTree {
        let mut nodes = vec![HuffNode { children: [-1, -1], sym: -1 }];
        let mut add = |code: u32, len: u8, sym: i32, nodes: &mut Vec<HuffNode>| {
            let mut cur = 0usize;
            for i in (0..len).rev() {
                let bit = ((code >> i) & 1) as usize;
                if nodes[cur].children[bit] < 0 {
                    nodes.push(HuffNode { children: [-1, -1], sym: -1 });
                    let idx = nodes.len() - 1;
                    nodes[cur].children[bit] = idx as i32;
                }
                cur = nodes[cur].children[bit] as usize;
            }
            nodes[cur].sym = sym;
        };
        for s in 0..256 {
            add(HUFFMAN_CODES[s], HUFFMAN_LENS[s], s as i32, &mut nodes);
        }
        // EOS
        add(0x3fffffff, 30, 256, &mut nodes);
        HuffTree { nodes }
    }

    pub fn decode(&self, data: &[u8]) -> Option<Vec<u8>> {
        let mut out = Vec::with_capacity(data.len() * 2);
        let mut cur = 0usize;
        let mut depth = 0;
        for &b in data {
            for i in (0..8).rev() {
                let bit = ((b >> i) & 1) as usize;
                let next = self.nodes[cur].children[bit];
                if next < 0 {
                    return None;
                }
                cur = next as usize;
                depth += 1;
                let sym = self.nodes[cur].sym;
                if sym >= 0 {
                    if sym == 256 {
                        return None;
                    }
                    out.push(sym as u8);
                    cur = 0;
                    depth = 0;
                }
            }
        }
        if depth > 7 {
            return None;
        }
        Some(out)
    }
}

pub fn encode_int(out: &mut Vec<u8>, first: u8, prefix_bits: u8, mut v: usize) {
    let max = (1usize << prefix_bits) - 1;
    if v < max {
        out.push(first | v as u8);
        return;
    }
    out.push(first | max as u8);
    v -= max;
    while v >= 128 {
        out.push((v % 128 + 128) as u8);
        v /= 128;
    }
    out.push(v as u8);
}

fn decode_int(buf: &[u8], pos: &mut usize, prefix_bits: u8) -> Option<usize> {
    let max = (1usize << prefix_bits) - 1;
    let first = *buf.get(*pos)? as usize & max;
    *pos += 1;
    if first < max {
        return Some(first);
    }
    let mut v = max;
    let mut m = 0;
    loop {
        let b = *buf.get(*pos)? as usize;
        *pos += 1;
        v = v.checked_add((b & 127).checked_shl(m)?)?;
        m += 7;
        if b & 128 == 0 {
            break;
        }
        if m > 28 {
            return None;
        }
    }
    Some(v)
}

/// Encode a header list using literals without indexing (no huffman).
pub fn encode_headers(headers: &[(String, String)]) -> Vec<u8> {
    let mut out = Vec::new();
    for (k, v) in headers {
        // find static name index
        let idx = STATIC_TABLE.iter().position(|(n, _)| *n == k.as_str());
        if let Some(i) = idx {
            if let Some(full) = STATIC_TABLE.iter().position(|(n, vv)| *n == k.as_str() && *vv == v.as_str()) {
                encode_int(&mut out, 0x80, 7, full + 1);
                continue;
            }
            encode_int(&mut out, 0x00, 4, i + 1);
        } else {
            out.push(0x00);
            encode_int(&mut out, 0x00, 7, k.len());
            out.extend_from_slice(k.as_bytes());
        }
        encode_int(&mut out, 0x00, 7, v.len());
        out.extend_from_slice(v.as_bytes());
    }
    out
}

pub struct Decoder {
    dynamic: std::collections::VecDeque<(Vec<u8>, Vec<u8>)>,
    size: usize,
    max_size: usize,
    huff: HuffTree,
}

impl Decoder {
    pub fn new() -> Decoder {
        Decoder { dynamic: std::collections::VecDeque::new(), size: 0, max_size: 4096, huff: HuffTree::new() }
    }

    fn get(&self, idx: usize) -> Option<(Vec<u8>, Vec<u8>)> {
        if idx == 0 {
            return None;
        }
        if idx <= 61 {
            let (n, v) = STATIC_TABLE[idx - 1];
            return Some((n.as_bytes().to_vec(), v.as_bytes().to_vec()));
        }
        self.dynamic.get(idx - 62).cloned()
    }

    fn evict(&mut self) {
        while self.size > self.max_size {
            if let Some((n, v)) = self.dynamic.pop_back() {
                self.size -= n.len() + v.len() + 32;
            } else {
                break;
            }
        }
    }

    fn insert(&mut self, n: Vec<u8>, v: Vec<u8>) {
        let sz = n.len() + v.len() + 32;
        self.dynamic.push_front((n, v));
        self.size += sz;
        self.evict();
    }

    fn read_string(&self, buf: &[u8], pos: &mut usize) -> Option<Vec<u8>> {
