//! Minimal HTTP/2 client (RFC 7540) with multiplexed streams.

use crate::client::{path_and_query, Client, ClientError, ConnectionTime, PreparedRequest, RequestResult, WorkResult};
use crate::hpack::{encode_headers, Decoder};
use crate::net::{Conn, Limits, NetError, ABORT};
use crate::runner::{Reserve, Schedule};
use rand::rngs::StdRng;
use rand::SeedableRng;
use std::collections::HashMap;
use std::sync::atomic::Ordering;
use std::sync::mpsc::Sender;
use std::sync::Arc;
use std::time::{Duration, Instant};

const PREFACE: &[u8] = b"PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n";
const T_DATA: u8 = 0;
const T_HEADERS: u8 = 1;
const T_RST: u8 = 3;
const T_SETTINGS: u8 = 4;
const T_PUSH: u8 = 5;
const T_PING: u8 = 6;
const T_GOAWAY: u8 = 7;
const T_WINDOW: u8 = 8;
const T_CONT: u8 = 9;
const F_END_STREAM: u8 = 0x1;
const F_ACK: u8 = 0x1;
const F_END_HEADERS: u8 = 0x4;
const F_PADDED: u8 = 0x8;
const F_PRIORITY: u8 = 0x20;
const MY_WINDOW: u32 = 0x7fff_ffff;

pub fn h2_error() -> ClientError {
    ClientError::Other("http2 error".to_string())
}

pub struct Stream {
    pub start: Instant,
    pub slc: Option<Instant>,
    pub first_byte: Option<Instant>,
    pub status: Option<u16>,
    pub headers: Vec<(String, Vec<u8>)>,
    pub body: Vec<u8>,
    pub keep_body: bool,
    pub body_len: usize,
    pub timeout: Option<Instant>,
    pub url_path: String,
    pending_body: Vec<u8>,
    send_window: i64,
    end_stream_sent: bool,
}

pub enum Done {
    Ok(u32, Stream),
    Err(u32, Stream, ClientError),
}

pub struct H2Conn {
    pub conn: Conn,
    rbuf: Vec<u8>,
    wbuf: Vec<u8>,
    decoder: Decoder,
    next_id: u32,
    pub streams: HashMap<u32, Stream>,
    peer_max_concurrent: usize,
    peer_initial_window: i64,
    peer_max_frame: usize,
    conn_send_window: i64,
    pub goaway: bool,
    header_block: Option<(u32, Vec<u8>, bool)>,
    consumed: u64,
    pub conn_time: ConnectionTime,
}

fn frame(out: &mut Vec<u8>, typ: u8, flags: u8, id: u32, payload: &[u8]) {
    let len = payload.len();
    out.push((len >> 16) as u8);
    out.push((len >> 8) as u8);
    out.push(len as u8);
    out.push(typ);
    out.push(flags);
    out.extend_from_slice(&(id & 0x7fff_ffff).to_be_bytes());
    out.extend_from_slice(payload);
}

fn connection_specific(name: &str) -> bool {
    matches!(name, "connection" | "keep-alive" | "proxy-connection" | "transfer-encoding" | "upgrade")
}

impl H2Conn {
    pub fn new(conn: Conn, conn_time: ConnectionTime) -> H2Conn {
        let mut c = H2Conn {
            conn,
            rbuf: Vec::with_capacity(65536),
            wbuf: Vec::with_capacity(65536),
            decoder: Decoder::new(),
            next_id: 1,
            streams: HashMap::new(),
            peer_max_concurrent: usize::MAX,
            peer_initial_window: 65535,
            peer_max_frame: 16384,
            conn_send_window: 65535,
            goaway: false,
            header_block: None,
            consumed: 0,
            conn_time,
        };
        c.wbuf.extend_from_slice(PREFACE);
        let mut settings = Vec::new();
        settings.extend_from_slice(&2u16.to_be_bytes());
        settings.extend_from_slice(&0u32.to_be_bytes());
        settings.extend_from_slice(&4u16.to_be_bytes());
        settings.extend_from_slice(&MY_WINDOW.to_be_bytes());
        frame(&mut c.wbuf, T_SETTINGS, 0, 0, &settings);
        frame(&mut c.wbuf, T_WINDOW, 0, 0, &(MY_WINDOW - 65535).to_be_bytes());
        c
    }

    pub fn active(&self) -> usize {
        self.streams.len()
    }

    pub fn can_open(&self, parallel: usize) -> bool {
        !self.goaway && self.streams.len() < parallel.min(self.peer_max_concurrent) && self.next_id < 0x7fff_fff0
    }

    pub fn start_request(&mut self, req: &PreparedRequest, start: Instant, slc: Option<Instant>, timeout: Option<Duration>, keep_body: bool) -> u32 {
        let id = self.next_id;
        self.next_id += 2;
        let mut hs: Vec<(String, String)> = Vec::new();
        hs.push((":method".into(), req.method.clone()));
        hs.push((":scheme".into(), req.url.scheme().to_string()));
        hs.push((":authority".into(), crate::client::authority(&req.url)));
        hs.push((":path".into(), path_and_query(&req.url)));
        let mut has_len = false;
        for (k, v) in &req.headers {
            if connection_specific(k) {
                continue;
            }
            if k == "te" && v != "trailers" {
                continue;
            }
            if k == "content-length" {
                has_len = true;
            }
            hs.push((k.clone(), v.clone()));
        }
        if !has_len && !req.body.is_empty() {
            hs.push(("content-length".into(), req.body.len().to_string()));
        }
        let block = encode_headers(&hs);
        let end_stream = req.body.is_empty();
        let max = self.peer_max_frame;
        if block.len() <= max {
            frame(
                &mut self.wbuf,
                T_HEADERS,
                F_END_HEADERS | if end_stream { F_END_STREAM } else { 0 },
                id,
                &block,
            );
        } else {
            let mut chunks = block.chunks(max);
            let first = chunks.next().unwrap();
            frame(&mut self.wbuf, T_HEADERS, if end_stream { F_END_STREAM } else { 0 }, id, first);
            let rest: Vec<&[u8]> = chunks.collect();
            for (i, c) in rest.iter().enumerate() {
                frame(&mut self.wbuf, T_CONT, if i + 1 == rest.len() { F_END_HEADERS } else { 0 }, id, c);
            }
        }
        let st = Stream {
            start,
            slc,
            first_byte: None,
            status: None,
            headers: Vec::new(),
            body: Vec::new(),
            keep_body,
            body_len: 0,
            timeout: timeout.map(|t| start + t),
            url_path: path_and_query(&req.url),
            pending_body: req.body.to_vec(),
            send_window: self.peer_initial_window,
            end_stream_sent: end_stream,
        };
        self.streams.insert(id, st);
        self.flush_bodies();
        id
    }

    fn flush_bodies(&mut self) {
        let max = self.peer_max_frame;
        let ids: Vec<u32> = self.streams.keys().cloned().collect();
        for id in ids {
            let st = self.streams.get_mut(&id).unwrap();
            while !st.end_stream_sent {
                let allowed = st.send_window.min(self.conn_send_window).max(0) as usize;
                if allowed == 0 && !st.pending_body.is_empty() {
                    break;
                }
                let n = st.pending_body.len().min(allowed).min(max);
                let chunk: Vec<u8> = st.pending_body.drain(..n).collect();
                let last = st.pending_body.is_empty();
                frame(&mut self.wbuf, T_DATA, if last { F_END_STREAM } else { 0 }, id, &chunk);
                st.send_window -= n as i64;
                self.conn_send_window -= n as i64;
                if last {
                    st.end_stream_sent = true;
                }
            }
        }
    }

    pub fn reset_stream(&mut self, id: u32) {
        frame(&mut self.wbuf, T_RST, 0, id, &8u32.to_be_bytes());
    }

    /// Perform I/O, waiting at most `wait`. Returns finished streams.
    pub fn poll(&mut self, wait: Duration, done: &mut Vec<Done>) -> Result<(), ClientError> {
        let fd = self.conn.fd();
        // write
        while !self.wbuf.is_empty() {
            let n = self.conn.try_write(&self.wbuf).map_err(|_| h2_error())?;
            if n == 0 {
                break;
            }
            self.wbuf.drain(..n);
        }
        let mut events = libc::POLLIN;
        if !self.wbuf.is_empty() {
            events |= libc::POLLOUT;
        }
        if !self.conn.tls_pending() {
            let mut pfd = libc::pollfd { fd, events, revents: 0 };
            let ms = (wait.as_micros() as i64 + 999) / 1000;
            unsafe {
                libc::poll(&mut pfd, 1, ms.clamp(0, 100) as i32);
            }
        }
        // read all available
        let mut buf = [0u8; 65536];
        loop {
            match self.conn.try_read(&mut buf) {
                Ok(Some(0)) => {
                    self.process(done)?;
                    return Err(h2_error());
                }
                Ok(Some(n)) => {
                    self.rbuf.extend_from_slice(&buf[..n]);
                }
                Ok(None) => break,
                Err(_) => return Err(h2_error()),
            }
        }
        self.process(done)?;
        while !self.wbuf.is_empty() {
            let n = self.conn.try_write(&self.wbuf).map_err(|_| h2_error())?;
            if n == 0 {
                break;
            }
            self.wbuf.drain(..n);
        }
        Ok(())
    }

    fn finish(&mut self, id: u32, done: &mut Vec<Done>) {
        if let Some(st) = self.streams.remove(&id) {
            if st.status.is_some() {
                done.push(Done::Ok(id, st));
            } else {
                done.push(Done::Err(id, st, h2_error()));
            }
        }
    }

    fn process(&mut self, done: &mut Vec<Done>) -> Result<(), ClientError> {
        let mut pos = 0;
        loop {
            if self.rbuf.len() - pos < 9 {
                break;
            }
            let h = &self.rbuf[pos..pos + 9];
            let len = ((h[0] as usize) << 16) | ((h[1] as usize) << 8) | h[2] as usize;
            let typ = h[3];
            let flags = h[4];
            let id = u32::from_be_bytes([h[5], h[6], h[7], h[8]]) & 0x7fff_ffff;
            if len > 1 << 24 {
                return Err(h2_error());
            }
            if self.rbuf.len() - pos < 9 + len {
                // sanity: first frame must be SETTINGS
                break;
            }
            let payload = self.rbuf[pos + 9..pos + 9 + len].to_vec();
            pos += 9 + len;
            if let Some((hid, _, _)) = &self.header_block {
                if typ != T_CONT || id != *hid {
                    return Err(h2_error());
                }
            }
            match typ {
                T_SETTINGS => {
                    if flags & F_ACK == 0 {
                        if len % 6 != 0 {
                            return Err(h2_error());
                        }
                        for c in payload.chunks(6) {
                            let k = u16::from_be_bytes([c[0], c[1]]);
                            let v = u32::from_be_bytes([c[2], c[3], c[4], c[5]]);
                            match k {
                                3 => self.peer_max_concurrent = v as usize,
                                4 => {
                                    let delta = v as i64 - self.peer_initial_window;
                                    self.peer_initial_window = v as i64;
                                    for st in self.streams.values_mut() {
                                        st.send_window += delta;
                                    }
                                }
                                5 => self.peer_max_frame = (v as usize).clamp(16384, 16_777_215),
                                _ => {}
                            }
                        }
                        frame(&mut self.wbuf, T_SETTINGS, F_ACK, 0, &[]);
                        self.flush_bodies();
                    }
                }
                T_PING => {
                    if flags & F_ACK == 0 {
                        frame(&mut self.wbuf, T_PING, F_ACK, 0, &payload);
                    }
                }
                T_WINDOW => {
                    if payload.len() >= 4 {
                        let inc = (u32::from_be_bytes([payload[0], payload[1], payload[2], payload[3]]) & 0x7fff_ffff) as i64;
                        if id == 0 {
                            self.conn_send_window += inc;
                        } else if let Some(st) = self.streams.get_mut(&id) {
                            st.send_window += inc;
                        }
                        self.flush_bodies();
                    }
                }
                T_GOAWAY => {
                    self.goaway = true;
                    let last = if payload.len() >= 4 {
                        u32::from_be_bytes([payload[0], payload[1], payload[2], payload[3]]) & 0x7fff_ffff
                    } else {
                        0
                    };
                    let ids: Vec<u32> = self.streams.keys().cloned().filter(|i| *i > last).collect();
                    for i in ids {
                        if let Some(st) = self.streams.remove(&i) {
                            done.push(Done::Err(i, st, h2_error()));
                        }
                    }
                }
                T_RST => {
                    if let Some(st) = self.streams.remove(&id) {
                        done.push(Done::Err(id, st, h2_error()));
                    }
                }
                T_HEADERS | T_PUSH => {
                    if typ == T_PUSH {
                        return Err(h2_error());
                    }
                    let mut p = &payload[..];
                    let mut pad = 0usize;
                    if flags & F_PADDED != 0 {
                        if p.is_empty() {
                            return Err(h2_error());
                        }
                        pad = p[0] as usize;
                        p = &p[1..];
                    }
                    if flags & F_PRIORITY != 0 {
                        if p.len() < 5 {
                            return Err(h2_error());
                        }
                        p = &p[5..];
                    }
                    if pad > p.len() {
                        return Err(h2_error());
                    }
                    let block = p[..p.len() - pad].to_vec();
                    let end_stream = flags & F_END_STREAM != 0;
                    if flags & F_END_HEADERS != 0 {
                        self.on_headers(id, &block, end_stream, done)?;
                    } else {
                        self.header_block = Some((id, block, end_stream));
                    }
                }
                T_CONT => {
                    let (hid, mut block, es) = match self.header_block.take() {
                        Some(x) => x,
                        None => return Err(h2_error()),
                    };
                    block.extend_from_slice(&payload);
                    if flags & F_END_HEADERS != 0 {
                        self.on_headers(hid, &block, es, done)?;
                    } else {
                        self.header_block = Some((hid, block, es));
                    }
                }
                T_DATA => {
                    let mut p = &payload[..];
                    let mut pad = 0usize;
                    if flags & F_PADDED != 0 {
                        if p.is_empty() {
                            return Err(h2_error());
                        }
                        pad = p[0] as usize;
                        p = &p[1..];
                    }
                    if pad > p.len() {
                        return Err(h2_error());
                    }
                    let data = &p[..p.len() - pad];
                    self.consumed += len as u64;
                    if let Some(st) = self.streams.get_mut(&id) {
                        st.body_len += data.len();
                        if st.keep_body {
                            st.body.extend_from_slice(data);
                        }
                    }
                    if flags & F_END_STREAM != 0 {
                        self.finish(id, done);
                    }
                    if self.consumed > (1 << 26) {
                        let inc = self.consumed as u32;
                        frame(&mut self.wbuf, T_WINDOW, 0, 0, &inc.to_be_bytes());
                        self.consumed = 0;
                    }
                }
                _ => {}
            }
        }
        self.rbuf.drain(..pos);
        // a non HTTP/2 peer: if the first bytes are not a frame header of SETTINGS, fail fast
        if self.rbuf.len() >= 9 && self.rbuf.starts_with(b"HTTP/") {
            return Err(h2_error());
        }
        Ok(())
    }

    fn on_headers(&mut self, id: u32, block: &[u8], end_stream: bool, done: &mut Vec<Done>) -> Result<(), ClientError> {
        let list = self.decoder.decode(block).ok_or_else(h2_error)?;
        if let Some(st) = self.streams.get_mut(&id) {
            let mut status = None;
            let mut hs = Vec::new();
            for (k, v) in list {
                if k == b":status" {
                    status = String::from_utf8_lossy(&v).parse::<u16>().ok();
                } else if !k.starts_with(b":") {
                    hs.push((String::from_utf8_lossy(&k).into_owned(), v));
                }
            }
            if let Some(s) = status {
                if (100..200).contains(&s) {
                    // informational, wait for the final response
                } else if st.status.is_none() {
                    st.status = Some(s);
                    st.headers = hs;
                    st.first_byte = Some(Instant::now());
                }
            }
        }
        if end_stream {
            self.finish(id, done);
        }
        Ok(())
    }
}

/// Establish an HTTP/2 connection for the url.
pub fn connect_h2(client: &Client, url: &url::Url, rng: &mut StdRng) -> Result<H2Conn, ClientError> {
    let start = Instant::now();
    let limits = Limits { timeout: None, deadline: None, abortable: true };
    let (conn, dns_done) = client.connect(url, rng, &limits, true)?;
    let ct = ConnectionTime { dns_lookup: dns_done - start, dialup: Instant::now() - start };
    Ok(H2Conn::new(conn, ct))
}

pub fn h2_worker(client: Arc<Client>, sched: Arc<Schedule>, tx: Sender<WorkResult>, parallel: usize, n_mode: bool) {
    let mut rng = StdRng::from_entropy();
    let parallel = parallel.max(1);
    let mut finished_sched = false;
    'outer: loop {
        if ABORT.load(Ordering::Relaxed) {
            break;
        }
        let url = match client.url_gen.generate(&mut rng) {
            Ok(u) => u,
            Err(e) => {
                match sched.try_reserve() {
                    Reserve::Done => break,
                    _ => {
                        if tx.send(Err(ClientError::Other(e))).is_err() {
                            break;
                        }
                        continue;
                    }
                }
            }
        };
        let mut h2 = match connect_h2(&client, &url, &mut rng) {
            Ok(c) => c,
            Err(e) => {
                // consume one ticket per failure
                match sched.try_reserve() {
                    Reserve::Done => break,
                    Reserve::At(t, _) => {
                        while Instant::now() < t && !ABORT.load(Ordering::Relaxed) {
                            std::thread::sleep(Duration::from_millis(5));
                        }
                        if e == ClientError::Deadline && n_mode {
                            break;
                        }
                        if tx.send(Err(e)).is_err() {
                            break;
                        }
                        continue;
                    }
                }
            }
        };
        let mut pending: Option<(Instant, Option<Instant>)> = None;
        let mut done = Vec::new();
        loop {
            if ABORT.load(Ordering::Relaxed) {
                if !n_mode {
                    for (_, _st) in h2.streams.drain() {
                        let _ = tx.send(Err(ClientError::Deadline));
                    }
                }
                break 'outer;
            }
            // open new streams
            while !finished_sched && h2.can_open(parallel) {
                let tk = match pending.take() {
                    Some(p) => Some(p),
                    None => match sched.try_reserve() {
                        Reserve::Done => {
                            finished_sched = true;
                            None
                        }
                        Reserve::At(t, slc) => Some((t, slc)),
                    },
                };
                let (t, slc) = match tk {
                    Some(x) => x,
                    None => break,
                };
                if t > Instant::now() {
                    pending = Some((t, slc));
                    break;
                }
                let start = Instant::now();
                let u = match client.url_gen.generate(&mut rng) {
                    Ok(u) => u,
                    Err(e) => {
                        let _ = tx.send(Err(ClientError::Other(e)));
                        continue;
                    }
                };
                let body = client.body_for_request(&mut rng);
                let req = client.prepare_h2(u, body);
                h2.start_request(&req, start, slc, client.timeout, false);
            }
            if finished_sched && h2.active() == 0 && pending.is_none() {
                break 'outer;
            }
            if h2.goaway && h2.active() == 0 {
                continue 'outer;
            }
            let now = Instant::now();
            let mut wait = Duration::from_millis(50);
            if let Some((t, _)) = pending {
                wait = wait.min(t.saturating_duration_since(now));
            }
            for st in h2.streams.values() {
                if let Some(t) = st.timeout {
                    wait = wait.min(t.saturating_duration_since(now));
                }
            }
            let res = h2.poll(wait, &mut done);
            // timeouts
            let now = Instant::now();
            let expired: Vec<u32> = h2
                .streams
                .iter()
                .filter(|(_, s)| s.timeout.map(|t| now >= t).unwrap_or(false))
                .map(|(k, _)| *k)
                .collect();
            for id in expired {
                if let Some(st) = h2.streams.remove(&id) {
                    h2.reset_stream(id);
                    done.push(Done::Err(id, st, ClientError::Timeout));
                }
            }
            for d in done.drain(..) {
                let r: WorkResult = match d {
                    Done::Ok(_, st) => Ok(RequestResult {
                        start_latency_correction: st.slc,
                        start: st.start,
                        connection_time: Some(h2.conn_time),
                        first_byte: st.first_byte,
                        end: Instant::now(),
                        status: st.status.unwrap_or(0),
                        len_bytes: st.body_len,
                        url_path: st.url_path,
                    }),
                    Done::Err(_, _, e) => Err(e),
                };
                if tx.send(r).is_err() {
                    break 'outer;
                }
            }
            if res.is_err() {
                for (_, _st) in h2.streams.drain() {
                    if tx.send(Err(h2_error())).is_err() {
                        break 'outer;
                    }
                }
                if let Some((_t, _slc)) = pending.take() {
                    // ticket consumed by a failing connection
                    if tx.send(Err(h2_error())).is_err() {
                        break 'outer;
                    }
                }
                continue 'outer;
            }
        }
    }
}

/// Run a single request for --debug.
pub fn debug_request(client: &Client, req: &PreparedRequest) -> Result<(u16, Vec<(String, Vec<u8>)>, Vec<u8>), String> {
    let mut rng = StdRng::from_entropy();
    let mut h2 = connect_h2(client, &req.url, &mut rng).map_err(|e| e.message())?;
    let start = Instant::now();
    h2.start_request(req, start, None, client.timeout, true);
    let mut done = Vec::new();
    loop {
        let res = h2.poll(Duration::from_millis(50), &mut done);
        if let Some(d) = done.pop() {
            return match d {
                Done::Ok(_, st) => Ok((st.status.unwrap_or(0), st.headers, st.body)),
                Done::Err(_, _, e) => Err(e.message()),
            };
        }
        if res.is_err() {
            return Err("http2 error".to_string());
        }
        if let Some(t) = client.timeout {
            if start.elapsed() >= t {
                return Err("timeout".to_string());
            }
        }
    }
}
