/// Format a duration like `1h 2m 3s 500ms`.
pub fn format_duration(d: Duration) -> String {
    let secs = d.as_secs();
    let nanos = d.subsec_nanos();
    if secs == 0 && nanos == 0 {
        return "0s".to_string();
    }
    let years = secs / 31_557_600;
    let ydays = secs % 31_557_600;
    let months = ydays / 2_630_016;
    let mdays = ydays % 2_630_016;
    let days = mdays / 86400;
    let day_secs = mdays % 86400;
    let hours = day_secs / 3600;
    let minutes = day_secs % 3600 / 60;
    let seconds = day_secs % 60;
    let millis = nanos / 1_000_000;
    let micros = nanos / 1000 % 1000;
    let nanosec = nanos % 1000;
    let mut parts: Vec<String> = Vec::new();
    let mut plural = |name: &str, v: u64, parts: &mut Vec<String>| {
        if v > 0 {
            parts.push(format!("{}{}{}", v, name, if v > 1 { "s" } else { "" }));
        }
    };
    plural("year", years, &mut parts);
    plural("month", months, &mut parts);
